window.COURSE_TR=window.COURSE_TR||{};COURSE_TR.es=COURSE_TR.es||{};COURSE_TR.es.en={"Begrüßen · sich vorstellen · nach dem Befinden fragen · Aussprache": "Greeting · introducing yourself · asking how someone is · pronunciation", "Verabschiedungen": "Saying goodbye", "Aussprache: c, ch, g, h, j, ll, ñ, qu, r/rr, v, y, z": "Pronunciation: c, ch, g, h, j, ll, ñ, qu, r/rr, v, y, z", "Erster Tag an der FIB": "First day at the FIB", "Erster Tag im MIRI an der FIB (Campus Nord, UPC). Vor dem Hörsaal A5 spricht dich eine Kommilitonin an.": "First day of the MIRI at the FIB (Campus Nord, UPC). In front of lecture hall A5 a fellow student starts talking to you.", "Begrüße Laia, stell dich vor (Name), frag, wie es ihr geht, und verabschiede dich passend.": "Greet Laia, introduce yourself (name), ask how she is and say goodbye appropriately.", "Begrüßen & vorstellen": "Greeting & introducing yourself", "Begrüßung nach Tageszeit": "Greetings by time of day", "<p>Im Spanischen hängt die Begrüßung von der Uhrzeit ab – und Spanier essen spät, deshalb verschieben sich die Grenzen:</p>\n <table><tr><th>Begrüßung</th><th>Wann?</th><th>Deutsch</th></tr>\n <tr><td class=\"es-t\">Buenos días</td><td>ca. 6:00 – 14:00</td><td>Guten Morgen / Tag</td></tr>\n <tr><td class=\"es-t\">Buenas tardes</td><td>ca. 14:00 – 20:00</td><td>Guten Tag / Abend</td></tr>\n <tr><td class=\"es-t\">Buenas noches</td><td>ab ca. 20:00</td><td>Guten Abend / Gute Nacht</td></tr>\n <tr><td class=\"es-t\">Hola</td><td>immer</td><td>Hallo</td></tr></table>\n <div class=\"ex\">Sehr typisch: <span class=\"es-t\">¡Hola, buenos días!</span> – beides kombiniert.</div>\n <div class=\"ojo\">„Buenas tardes“ sagt man in Spanien bis ca. 20–21 Uhr – also auch um 19 Uhr, wo wir „Guten Abend“ sagen würden.</div>": "<p>In Spanish the greeting depends on the time of day – and Spaniards eat late, so the boundaries shift:</p>\n <table><tr><th>Greeting</th><th>When?</th><th>English</th></tr>\n <tr><td class=\"es-t\">Buenos días</td><td>approx. 6:00 – 14:00</td><td>Good morning</td></tr>\n <tr><td class=\"es-t\">Buenas tardes</td><td>approx. 14:00 – 20:00</td><td>Good afternoon / evening</td></tr>\n <tr><td class=\"es-t\">Buenas noches</td><td>from approx. 20:00</td><td>Good evening / good night</td></tr>\n <tr><td class=\"es-t\">Hola</td><td>always</td><td>Hello</td></tr></table>\n <div class=\"ex\">Very typical: <span class=\"es-t\">¡Hola, buenos días!</span> – both combined.</div>\n <div class=\"ojo\">In Spain you say “Buenas tardes” until about 8–9 pm – so also at 7 pm, when in English you'd already say “Good evening”.</div>", "hallo": "hello", "guten Morgen / guten Tag": "good morning", "guten Tag (nachmittags)": "good afternoon", "guten Abend / gute Nacht": "good evening / good night", "Wie heißt du?": "What's your name?", "Wie heißen Sie?": "What's your name? (formal)", "ich heiße …": "my name is …", "ich bin …": "I am …", "und du?": "and you?", "und Sie?": "and you? (formal)", "Sich vorstellen: tú oder usted?": "Introducing yourself: tú or usted?", "<table><tr><th></th><th>informell (tú)</th><th>formell (usted)</th></tr>\n <tr><td>Name erfragen</td><td class=\"es-t\">¿Cómo te llamas?</td><td class=\"es-t\">¿Cómo se llama usted?</td></tr>\n <tr><td>Antwort</td><td class=\"es-t\">Me llamo Jonas. ¿Y tú?</td><td class=\"es-t\">Soy Jonas Gross. ¿Y usted?</td></tr></table>\n <p><b>tú</b> = du, <b>usted</b> = Sie. Spanier duzen sehr schnell – unter Studierenden, Kollegen und oft sogar mit Chefs. <b>usted</b> benutzt du bei älteren Menschen, in Behörden oder sehr formellen Situationen.</p>\n <div class=\"ojo\"><span class=\"es-t\">usted</span> verwendet die Verbform der 3. Person (wie „er/sie“): <span class=\"es-t\">¿Cómo se llama usted?</span></div>": "<table><tr><th></th><th>informal (tú)</th><th>formal (usted)</th></tr>\n <tr><td>Asking the name</td><td class=\"es-t\">¿Cómo te llamas?</td><td class=\"es-t\">¿Cómo se llama usted?</td></tr>\n <tr><td>Answer</td><td class=\"es-t\">Me llamo Jonas. ¿Y tú?</td><td class=\"es-t\">Soy Jonas Gross. ¿Y usted?</td></tr></table>\n <p><b>tú</b> = informal “you”, <b>usted</b> = polite “you”. Spaniards switch to <b>tú</b> very quickly – among students, colleagues and often even with bosses. Use <b>usted</b> with older people, at public offices or in very formal situations.</p>\n <div class=\"ojo\"><span class=\"es-t\">usted</span> takes the 3rd-person verb form (like “he/she”): <span class=\"es-t\">¿Cómo se llama usted?</span></div>", "Es ist 16:00 Uhr. Wie begrüßt du deine neue Kollegin?": "It's 4 pm. How do you greet your new colleague?", "Zwischen ca. 14:00 und 20:00 Uhr sagt man <i>buenas tardes</i>.": "Between about 14:00 and 20:00 you say <i>buenas tardes</i>.", "Wie fragst du deinen Kommilitonen nach seinem Namen?": "How do you ask your fellow student for his name?", "Unter Studierenden duzt man sich: <i>¿Cómo te llamas?</i>": "Students use <i>tú</i> with each other: <i>¿Cómo te llamas?</i>", "llamarse = heißen": "llamarse = to be called", "Bei <i>usted</i> nimmt man die 3. Person: <i>se llama</i>.": "With <i>usted</i> you use the 3rd person: <i>se llama</i>.", "Du kommst in den Seminarraum. Ein Student setzt sich neben dich.": "You walk into the seminar room. A student sits down next to you.", "Hallo! Ich bin Marc. Und du? Wie heißt du?": "Hi! I'm Marc. And you? What's your name?", "Es ist morgens im Seminar – <i>buenas noches</i> passt erst ab ca. 20 Uhr.": "It's morning in the seminar – <i>buenas noches</i> only fits from about 8 pm.", "Marc hat nach <b>deinem</b> Namen gefragt – und unter Studierenden duzt man sich.": "Marc asked for <b>your</b> name – and students use <i>tú</i> with each other.", "Freut mich, Jonas.": "Nice to meet you, Jonas.", "Hallo, ich heiße Jonas. Und du?": "Hi, my name is Jonas. And you?", "Guten Tag (morgens), wie heißen Sie?": "Good morning, what's your name? (formal)", "Formell: <i>¿Cómo se llama usted?</i> – morgens <i>buenos días</i>.": "Formal: <i>¿Cómo se llama usted?</i> – in the morning <i>buenos días</i>.", "Hallo, guten Morgen. Ich heiße Jonas.": "Hello, good morning. My name is Jonas.", "Das <b>ll</b> in <i>llamo</i> spricht man wie ein deutsches <b>j</b> („jamo“).": "The <b>ll</b> in <i>llamo</i> sounds like the <b>y</b> in “yes” (“yamo”).", "Wie geht’s? & Verabschieden": "How are you? & saying goodbye", "Nach dem Befinden fragen": "Asking how someone is", "Wie geht’s?": "How's it going?", "Wie geht es dir?": "How are you?", "Wie geht es Ihnen?": "How are you? (formal)", "gut": "fine / well", "sehr gut": "very well", "so lala": "so-so", "schlecht": "bad", "danke": "thank you", "freut mich (m / w)": "nice to meet you (m / f)", "sehr erfreut": "pleased to meet you", "<table><tr><th>Frage</th><th>Antwort</th></tr>\n <tr><td class=\"es-t\">¿Qué tal?</td><td class=\"es-t\">Bien, ¿y tú?</td></tr>\n <tr><td class=\"es-t\">¿Cómo estás? <span class=\"muted\">(tú)</span></td><td class=\"es-t\">Muy bien, gracias. ¿Y tú?</td></tr>\n <tr><td class=\"es-t\">¿Cómo está usted? <span class=\"muted\">(usted)</span></td><td class=\"es-t\">Bien, gracias. ¿Y usted?</td></tr></table>\n <div class=\"ex\"><b>¿Qué tal?</b> passt immer – formell und informell. Oft ist es nur ein Gruß, keine echte Frage: <span class=\"es-t\">¡Hola! ¿Qué tal?</span></div>\n <div class=\"ojo\">Wenn du dich freust, jemanden kennenzulernen: Männer sagen <span class=\"es-t\">encantado</span>, Frauen <span class=\"es-t\">encantada</span> – es richtet sich nach dem/der <b>Sprechenden</b>.</div>": "<table><tr><th>Question</th><th>Answer</th></tr>\n <tr><td class=\"es-t\">¿Qué tal?</td><td class=\"es-t\">Bien, ¿y tú?</td></tr>\n <tr><td class=\"es-t\">¿Cómo estás? <span class=\"muted\">(tú)</span></td><td class=\"es-t\">Muy bien, gracias. ¿Y tú?</td></tr>\n <tr><td class=\"es-t\">¿Cómo está usted? <span class=\"muted\">(usted)</span></td><td class=\"es-t\">Bien, gracias. ¿Y usted?</td></tr></table>\n <div class=\"ex\"><b>¿Qué tal?</b> always works – formal and informal. Often it's just a greeting, not a real question: <span class=\"es-t\">¡Hola! ¿Qué tal?</span></div>\n <div class=\"ojo\">When you're pleased to meet someone: men say <span class=\"es-t\">encantado</span>, women <span class=\"es-t\">encantada</span> – it depends on the <b>speaker</b>.</div>", "tschüss / auf Wiedersehen": "bye / goodbye", "bis später / tschüss": "see you later / bye", "bis bald": "see you soon", "bis morgen": "see you tomorrow", "bis zum nächsten Mal": "until next time", "auf Wiedersehen": "goodbye", "ciao (umgangssprachlich)": "ciao (colloquial)", "Begrüßung oder Verabschiedung? Ordne die Bedeutung zu.": "Greeting or goodbye? Match the meanings.", "bis später": "see you later", "wie geht’s?": "how's it going?", "Pablo trifft Laia. Er sagt: „Encantado“. Laia antwortet:": "Pablo meets Laia. He says: “Encantado”. Laia answers:", "Laia ist eine Frau → <i>encantada</i>. Die Form richtet sich nach der Person, die spricht.": "Laia is a woman → <i>encantada</i>. The form depends on the person speaking.", "<i>bien</i> = gut; <i>¿y tú?</i> = und du?": "<i>bien</i> = fine; <i>¿y tú?</i> = and you?", "Du gehst um 18 Uhr aus der Uni und siehst deine Kommilitonen morgen wieder. Was sagst du?": "You leave the university at 6 pm and will see your fellow students again tomorrow. What do you say?", "Du gehst zur Secretaría, um deine Unterlagen abzugeben. Eine ältere Mitarbeiterin begrüßt dich. Hier ist <b>usted</b> angebracht.": "You go to the Secretaría to hand in your documents. An older staff member greets you. Here <b>usted</b> is appropriate.", "Guten Morgen. Wie heißen Sie?": "Good morning. What's your name? (formal)", "Sie hat <i>buenos días</i> gesagt – es ist Vormittag.": "She said <i>buenos días</i> – it's morning.", "Das ist eine Antwort auf <i>¿Qué tal?</i>, nicht auf die Frage nach dem Namen.": "That's an answer to <i>¿Qué tal?</i>, not to the question about your name.", "Sehr gut, Herr Gross. Wie geht es Ihnen?": "Very good, Mr Gross. How are you? (formal)", "Sie siezt dich – also antwortest du mit <i>¿y usted?</i>": "She's using <i>usted</i> with you – so you answer with <i>¿y usted?</i>", "Du willst dich noch nicht verabschieden 😉": "You don't want to say goodbye yet 😉", "Gut, danke. Einen Moment, bitte.": "Fine, thank you. One moment, please.", "Fertig. Auf Wiedersehen!": "Done. Goodbye!", "Sie verabschiedet sich – du auch: <i>Adiós / Hasta luego</i>.": "She's saying goodbye – so do you: <i>Adiós / Hasta luego</i>.", "formell: <i>¿Cómo está usted?</i>": "formal: <i>¿Cómo está usted?</i>", "Gut, danke. Und dir?": "Fine, thanks. And you?", "„und dir?“ = ¿y tú?": "“and you?” = ¿y tú?", "sehr gut, danke": "very well, thank you", "Die Buchstaben, die anders klingen als im Deutschen": "Letters that sound different from English", "<table><tr><th>Buchstabe</th><th>Beispiel</th><th>Aussprache</th></tr>\n <tr><td><b>c</b> + a, o, u</td><td class=\"es-t\">Cataluña</td><td>wie <b>k</b></td></tr>\n <tr><td><b>c</b> + e, i / <b>z</b></td><td class=\"es-t\">cinco, Zara</td><td>gelispelt wie engl. <i>th</i> (in Lateinamerika wie <b>s</b>)</td></tr>\n <tr><td><b>ch</b></td><td class=\"es-t\">Chupa Chups</td><td>wie <b>tsch</b></td></tr>\n <tr><td><b>g</b> + a, o, u</td><td class=\"es-t\">gracias, gol</td><td>wie <b>g</b> – bei <b>gue, gui</b> ist das u stumm: <span class=\"es-t\">Miguel</span></td></tr>\n <tr><td><b>g</b> + e, i / <b>j</b></td><td class=\"es-t\">Argentina, jamón</td><td>wie <b>ch</b> in „Sache“</td></tr>\n <tr><td><b>h</b></td><td class=\"es-t\">hotel, hola</td><td>stumm!</td></tr>\n <tr><td><b>ll</b> / <b>y</b></td><td class=\"es-t\">llamo, playa</td><td>wie <b>j</b> in „Junge“ – <b>y</b> am Wortende wie <b>i</b>: <span class=\"es-t\">Uruguay</span></td></tr>\n <tr><td><b>ñ</b></td><td class=\"es-t\">España</td><td>wie <b>gn</b> in „Champagner“</td></tr>\n <tr><td><b>qu</b></td><td class=\"es-t\">queso</td><td>wie <b>k</b>, das u ist stumm</td></tr>\n <tr><td><b>r</b> / <b>rr</b></td><td class=\"es-t\">Barcelona / Renfe, perro</td><td>einfach gerollt / am Wortanfang & <b>rr</b> stark gerollt</td></tr>\n <tr><td><b>v</b></td><td class=\"es-t\">Valencia</td><td>wie <b>b</b> – kein Unterschied zu b</td></tr></table>\n <div class=\"ojo\">In Barcelona hörst du auch Katalanisch – das klingt anders (z. B. <i>Bon dia</i>). Hier lernen wir castellano.</div>": "<table><tr><th>Letter</th><th>Example</th><th>Pronunciation</th></tr>\n <tr><td><b>c</b> + a, o, u</td><td class=\"es-t\">Cataluña</td><td>like <b>k</b></td></tr>\n <tr><td><b>c</b> + e, i / <b>z</b></td><td class=\"es-t\">cinco, Zara</td><td>like <i>th</i> in “think” (in Latin America like <b>s</b>)</td></tr>\n <tr><td><b>ch</b></td><td class=\"es-t\">Chupa Chups</td><td>like <b>ch</b> in “church”</td></tr>\n <tr><td><b>g</b> + a, o, u</td><td class=\"es-t\">gracias, gol</td><td>like <b>g</b> in “go” – in <b>gue, gui</b> the u is silent: <span class=\"es-t\">Miguel</span></td></tr>\n <tr><td><b>g</b> + e, i / <b>j</b></td><td class=\"es-t\">Argentina, jamón</td><td>like <b>ch</b> in Scottish “loch” (a strong h)</td></tr>\n <tr><td><b>h</b></td><td class=\"es-t\">hotel, hola</td><td>silent!</td></tr>\n <tr><td><b>ll</b> / <b>y</b></td><td class=\"es-t\">llamo, playa</td><td>like <b>y</b> in “yes” – <b>y</b> at the end of a word like <b>i</b>: <span class=\"es-t\">Uruguay</span></td></tr>\n <tr><td><b>ñ</b></td><td class=\"es-t\">España</td><td>like <b>ny</b> in “canyon”</td></tr>\n <tr><td><b>qu</b></td><td class=\"es-t\">queso</td><td>like <b>k</b>, the u is silent</td></tr>\n <tr><td><b>r</b> / <b>rr</b></td><td class=\"es-t\">Barcelona / Renfe, perro</td><td>a single tap / at the start of a word & <b>rr</b> strongly rolled</td></tr>\n <tr><td><b>v</b></td><td class=\"es-t\">Valencia</td><td>like <b>b</b> – no difference from b</td></tr></table>\n <div class=\"ojo\">In Barcelona you'll also hear Catalan – it sounds different (e.g. <i>Bon dia</i>). Here we learn castellano.</div>", "Wie spricht man das <b>h</b> in <span class=\"es-t\">hotel</span>?": "How do you pronounce the <b>h</b> in <span class=\"es-t\">hotel</span>?", "gar nicht": "not at all", "wie deutsches h": "like English h", "wie ch in Sache": "like ch in Scottish “loch”", "Welches Wort hat den „ch“-Laut wie in <i>Sache</i>?": "Which word has the throaty sound like <i>ch</i> in “loch”?", "<b>j</b> (und g vor e/i) klingt wie ch in „Sache“. <b>ch</b> in <i>chico</i> klingt wie „tsch“.": "<b>j</b> (and g before e/i) sounds like ch in “loch”. <b>ch</b> in <i>chico</i> sounds like “ch” in “church”.", "Bei welchem Wort wird das <b>u</b> NICHT gesprochen?": "In which word is the <b>u</b> NOT pronounced?", "In <b>gue/gui</b> und <b>que/qui</b> ist das u stumm.": "In <b>gue/gui</b> and <b>que/qui</b> the u is silent.", "Hör zu und schreib den Städtenamen.": "Listen and write the name of the city.", "Das <b>ñ</b> – auf dem Mac: <span class=\"kbd\">⌥ n</span>, dann <span class=\"kbd\">n</span>. Oder die Taste unter dem Eingabefeld.": "The <b>ñ</b> – on a Mac: <span class=\"kbd\">⌥ n</span>, then <span class=\"kbd\">n</span>. Or use the button below the input field.", "v klingt wie b, c vor e/i gelispelt.": "v sounds like b, c before e/i like “th”.", "Zungenbrecher mit rr (Renfe = spanische Bahn)": "Tongue twister with rr (Renfe = Spanish railways)", "r am Wortanfang und rr stark rollen!": "Roll the r at the start of a word and the rr strongly!", "Zungenbrecher mit j": "Tongue twister with j", "j = ch wie in „Sache“.": "j = like ch in “loch”.", "Zungenbrecher mit z/c": "Tongue twister with z/c", "z und c vor e/i: Zungenspitze zwischen die Zähne (wie engl. th).": "z and c before e/i: tip of the tongue between the teeth (like English th).", "<h3>Begrüßen</h3><table><tr><td class=\"es-t\">Hola</td><td>Hallo</td></tr><tr><td class=\"es-t\">Buenos días</td><td>bis ca. 14 Uhr</td></tr><tr><td class=\"es-t\">Buenas tardes</td><td>14–20 Uhr</td></tr><tr><td class=\"es-t\">Buenas noches</td><td>ab 20 Uhr</td></tr></table>\n<h3>Sich vorstellen</h3><table><tr><th>informell (tú)</th><th>formell (usted)</th></tr><tr><td class=\"es-t\">¿Cómo te llamas?</td><td class=\"es-t\">¿Cómo se llama usted?</td></tr><tr><td class=\"es-t\">Soy … / Me llamo … ¿Y tú?</td><td class=\"es-t\">Soy … / Me llamo … ¿Y usted?</td></tr></table>\n<h3>Nach dem Befinden fragen</h3><table><tr><td class=\"es-t\">¿Qué tal? / ¿Cómo estás?</td><td class=\"es-t\">Bien / Muy bien / Regular, ¿y tú?</td></tr><tr><td class=\"es-t\">¿Cómo está usted?</td><td class=\"es-t\">Muy bien, gracias. ¿Y usted?</td></tr></table>\n<h3>Verabschieden</h3><p class=\"es-t\">Adiós · Hasta luego · Hasta pronto · Hasta mañana · Hasta la próxima</p>\n<h3>Aussprache</h3><p>h stumm · j / ge, gi = ch (Sache) · ll, y = j · ñ = gn · qu = k · c (e, i), z = th · v = b · rr gerollt</p>": "<h3>Greeting</h3><table><tr><td class=\"es-t\">Hola</td><td>Hello</td></tr><tr><td class=\"es-t\">Buenos días</td><td>until about 2 pm</td></tr><tr><td class=\"es-t\">Buenas tardes</td><td>2–8 pm</td></tr><tr><td class=\"es-t\">Buenas noches</td><td>from 8 pm</td></tr></table>\n<h3>Introducing yourself</h3><table><tr><th>informal (tú)</th><th>formal (usted)</th></tr><tr><td class=\"es-t\">¿Cómo te llamas?</td><td class=\"es-t\">¿Cómo se llama usted?</td></tr><tr><td class=\"es-t\">Soy … / Me llamo … ¿Y tú?</td><td class=\"es-t\">Soy … / Me llamo … ¿Y usted?</td></tr></table>\n<h3>Asking how someone is</h3><table><tr><td class=\"es-t\">¿Qué tal? / ¿Cómo estás?</td><td class=\"es-t\">Bien / Muy bien / Regular, ¿y tú?</td></tr><tr><td class=\"es-t\">¿Cómo está usted?</td><td class=\"es-t\">Muy bien, gracias. ¿Y usted?</td></tr></table>\n<h3>Saying goodbye</h3><p class=\"es-t\">Adiós · Hasta luego · Hasta pronto · Hasta mañana · Hasta la próxima</p>\n<h3>Pronunciation</h3><p>h silent · j / ge, gi = ch (loch) · ll, y = y (yes) · ñ = ny · qu = k · c (e, i), z = th · v = b · rr rolled</p>", "Nach der Bedeutung fragen · Zahlen bis 10 · Herkunft · Fragen stellen · warum man Spanisch lernt · Zustimmung & Widerspruch": "Asking what something means · numbers up to 10 · origin · asking questions · why you learn Spanish · agreeing & disagreeing", "Substantive: Genus & Plural": "Nouns: gender & plural", "Zahlen 0–10": "Numbers 0–10", "ser + Subjektpronomen": "ser + subject pronouns", "Verben auf -ar": "Verbs ending in -ar", "Fragewörter": "Question words", "Ein Sprach-Tandem-Abend in einer Bar in Gràcia. Ein Spanier setzt sich zu dir an den Tisch.": "A language-exchange evening in a bar in Gràcia. A Spanish guy sits down at your table.", "Stell dich vor, sag, woher du kommst, welche Sprachen du sprichst und warum du Spanisch lernst. Frag Pau dasselbe.": "Introduce yourself, say where you're from, which languages you speak and why you're learning Spanish. Ask Pau the same.", "Männlich oder weiblich?": "Masculine or feminine?", "<p>Im Spanischen gibt es nur <b>zwei</b> Geschlechter – kein „das“.</p>\n <table><tr><th>Endung</th><th>meist …</th><th>Beispiele</th></tr>\n <tr><td><b>-o</b></td><td>männlich (el)</td><td class=\"es-t\">el producto, el equipo</td></tr>\n <tr><td><b>-a, -dad, -ción</b></td><td>weiblich (la)</td><td class=\"es-t\">la empresa, la ciudad, la exposición</td></tr>\n <tr><td><b>-e</b> / Konsonant</td><td>beides möglich → mit Artikel lernen!</td><td class=\"es-t\">el hotel, la imagen, el arte</td></tr></table>\n <div class=\"ojo\">Ausnahmen: <span class=\"es-t\">el día</span>, <span class=\"es-t\">el programa</span>, <span class=\"es-t\">la foto</span>, <span class=\"es-t\">la mano</span>.</div>": "<p>Spanish has only <b>two</b> genders – there is no neuter.</p>\n <table><tr><th>Ending</th><th>usually …</th><th>Examples</th></tr>\n <tr><td><b>-o</b></td><td>masculine (el)</td><td class=\"es-t\">el producto, el equipo</td></tr>\n <tr><td><b>-a, -dad, -ción</b></td><td>feminine (la)</td><td class=\"es-t\">la empresa, la ciudad, la exposición</td></tr>\n <tr><td><b>-e</b> / consonant</td><td>either → learn it with the article!</td><td class=\"es-t\">el hotel, la imagen, el arte</td></tr></table>\n <div class=\"ojo\">Exceptions: <span class=\"es-t\">el día</span>, <span class=\"es-t\">el programa</span>, <span class=\"es-t\">la foto</span>, <span class=\"es-t\">la mano</span>.</div>", "<table><tr><th></th><th>männlich</th><th>weiblich</th></tr>\n <tr><td>bestimmt Sg.</td><td class=\"es-t\">el producto</td><td class=\"es-t\">la página</td></tr>\n <tr><td>bestimmt Pl.</td><td class=\"es-t\">los productos</td><td class=\"es-t\">las páginas</td></tr>\n <tr><td>unbestimmt Sg.</td><td class=\"es-t\">un producto</td><td class=\"es-t\">una página</td></tr>\n <tr><td>unbestimmt Pl.</td><td class=\"es-t\">unos productos</td><td class=\"es-t\">unas páginas</td></tr></table>\n <p><b>Plural:</b> Vokal + <b>-s</b> (<span class=\"es-t\">equipo → equipos</span>), Konsonant + <b>-es</b> (<span class=\"es-t\">hotel → hoteles</span>, <span class=\"es-t\">ciudad → ciudades</span>).</p>\n <div class=\"ojo\">Akzent auf der letzten Silbe fällt im Plural weg: <span class=\"es-t\">exposición → exposiciones</span>, <span class=\"es-t\">jamón → jamones</span>.</div>\n <p><span class=\"es-t\">unos / unas</span> heißt „einige“.</p>": "<table><tr><th></th><th>masculine</th><th>feminine</th></tr>\n <tr><td>definite sg.</td><td class=\"es-t\">el producto</td><td class=\"es-t\">la página</td></tr>\n <tr><td>definite pl.</td><td class=\"es-t\">los productos</td><td class=\"es-t\">las páginas</td></tr>\n <tr><td>indefinite sg.</td><td class=\"es-t\">un producto</td><td class=\"es-t\">una página</td></tr>\n <tr><td>indefinite pl.</td><td class=\"es-t\">unos productos</td><td class=\"es-t\">unas páginas</td></tr></table>\n <p><b>Plural:</b> vowel + <b>-s</b> (<span class=\"es-t\">equipo → equipos</span>), consonant + <b>-es</b> (<span class=\"es-t\">hotel → hoteles</span>, <span class=\"es-t\">ciudad → ciudades</span>).</p>\n <div class=\"ojo\">An accent on the last syllable disappears in the plural: <span class=\"es-t\">exposición → exposiciones</span>, <span class=\"es-t\">jamón → jamones</span>.</div>\n <p><span class=\"es-t\">unos / unas</span> means “some”.</p>", "Wichtige Wörter": "Important words", "das Unternehmen": "the company", "das Produkt": "the product", "das Hotel": "the hotel", "die Stadt": "the city", "das Land": "the country", "das Essen": "the food", "der Sport": "the sport", "die Technologie": "the technology", "das soziale Netzwerk": "the social network", "die Werbung": "the advertising", "der Erfolg": "the success", "die Messe": "the trade fair", "der Tourismus": "the tourism", "das Fest / die Party": "the party / festival", "Wörter auf <b>-dad</b> sind weiblich.": "Words ending in <b>-dad</b> are feminine.", "Ausnahme! Viele Wörter auf <b>-ma</b> aus dem Griechischen sind männlich: <i>el problema, el programa, el sistema</i>.": "Exception! Many words ending in <b>-ma</b> from Greek are masculine: <i>el problema, el programa, el sistema</i>.", "Wörter auf <b>-ción</b> sind weiblich.": "Words ending in <b>-ción</b> are feminine.", "Setz den Plural ein.": "Put it in the plural.", "Konsonant + -es.": "Consonant + -es.", "Konsonant + -es, und der Akzent fällt weg.": "Consonant + -es, and the accent disappears.", "Ergänze den unbestimmten Artikel (un / una).": "Add the indefinite article (un / una).", "Singular und Plural": "Singular and plural", "die Unternehmen (Plural)": "the companies (plural)", "ein Hotel": "a hotel", "Im Unterricht nach Wörtern fragen": "Asking about words in class", "Welche Zahl hörst du? Schreib sie als Wort.": "Which number do you hear? Write it as a word.", "<table><tr><th>Frage</th><th>Antwort</th></tr>\n <tr><td class=\"es-t\">¿Qué significa «red social»?</td><td class=\"es-t\">Creo que significa …</td></tr>\n <tr><td class=\"es-t\">¿«Red» significa «Netz»?</td><td class=\"es-t\">Sí. / No. / No sé.</td></tr>\n <tr><td class=\"es-t\">¿Cómo se dice «Messe» en español?</td><td class=\"es-t\">Se dice «feria».</td></tr>\n <tr><td class=\"es-t\">¿Puedes repetir, por favor?</td><td>Kannst du das wiederholen?</td></tr>\n <tr><td class=\"es-t\">Más despacio, por favor.</td><td>Langsamer, bitte.</td></tr></table>": "<table><tr><th>Question</th><th>Answer</th></tr>\n <tr><td class=\"es-t\">¿Qué significa «red social»?</td><td class=\"es-t\">Creo que significa …</td></tr>\n <tr><td class=\"es-t\">¿«Red» significa «network»?</td><td class=\"es-t\">Sí. / No. / No sé.</td></tr>\n <tr><td class=\"es-t\">¿Cómo se dice «trade fair» en español?</td><td class=\"es-t\">Se dice «feria».</td></tr>\n <tr><td class=\"es-t\">¿Puedes repetir, por favor?</td><td>Can you repeat that?</td></tr>\n <tr><td class=\"es-t\">Más despacio, por favor.</td><td>More slowly, please.</td></tr></table>", "Sätze für den Unterricht": "Phrases for class", "Was bedeutet …?": "What does … mean?", "ich glaube, es bedeutet …": "I think it means …", "ich weiß nicht": "I don't know", "Wie sagt man … auf Spanisch?": "How do you say … in Spanish?", "Kannst du das wiederholen, bitte?": "Can you repeat that, please?", "langsamer, bitte": "more slowly, please", "Du verstehst das Wort „sostenibilidad“ nicht. Was fragst du?": "You don't understand the word “sostenibilidad”. What do you ask?", "Wie sagt man „Werbung“ auf Spanisch?": "How do you say “advertising” in Spanish?", "Ich weiß nicht.": "I don't know.", "Das Verb ser (sein)": "The verb ser (to be)", "<table><tr><th>Pronomen</th><th>ser</th></tr>\n <tr><td>yo</td><td class=\"es-t\">soy</td></tr><tr><td>tú</td><td class=\"es-t\">eres</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">es</td></tr>\n <tr><td>nosotros / nosotras</td><td class=\"es-t\">somos</td></tr><tr><td>vosotros / vosotras</td><td class=\"es-t\">sois</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">son</td></tr></table>\n <div class=\"ex\"><b>Subjektpronomen</b> (yo, tú …) lässt man normalerweise weg – die Verbform zeigt schon, wer gemeint ist: <span class=\"es-t\">Soy de Alemania.</span><br>Man benutzt sie nur zur Betonung oder Unterscheidung: <span class=\"es-t\">Yo soy de Mannheim y ella es de Girona.</span></div>\n <div class=\"ojo\">In Lateinamerika sagt man <span class=\"es-t\">ustedes</span> statt <span class=\"es-t\">vosotros</span> – auch beim Duzen.</div>": "<table><tr><th>Pronoun</th><th>ser</th></tr>\n <tr><td>yo</td><td class=\"es-t\">soy</td></tr><tr><td>tú</td><td class=\"es-t\">eres</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">es</td></tr>\n <tr><td>nosotros / nosotras</td><td class=\"es-t\">somos</td></tr><tr><td>vosotros / vosotras</td><td class=\"es-t\">sois</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">son</td></tr></table>\n <div class=\"ex\"><b>Subject pronouns</b> (yo, tú …) are usually left out – the verb form already shows who is meant: <span class=\"es-t\">Soy de Alemania.</span><br>You only use them for emphasis or contrast: <span class=\"es-t\">Yo soy de Mannheim y ella es de Girona.</span></div>\n <div class=\"ojo\">In Latin America people say <span class=\"es-t\">ustedes</span> instead of <span class=\"es-t\">vosotros</span> – even informally.</div>", "sein": "to be", "Woher kommst du?": "Where are you from?", "<table><tr><th>Frage</th><th>Antwort</th></tr>\n <tr><td class=\"es-t\">¿De dónde eres?</td><td class=\"es-t\">Soy de Alemania.</td></tr>\n <tr><td class=\"es-t\">¿De dónde es usted?</td><td class=\"es-t\">Soy de Holanda.</td></tr>\n <tr><td class=\"es-t\">¿Eres de España?</td><td class=\"es-t\">No, soy de Chile.</td></tr>\n <tr><td class=\"es-t\">¿Sois de Colombia?</td><td class=\"es-t\">Sí, de Bogotá.</td></tr>\n <tr><td class=\"es-t\">¿Son ustedes de Madrid?</td><td class=\"es-t\">No, somos de Vigo.</td></tr></table>\n <p><b>Verneinung:</b> <span class=\"es-t\">no</span> steht immer <b>vor dem Verb</b>: <span class=\"es-t\">Messi no es de Barcelona.</span> In der Antwort oft doppelt: <span class=\"es-t\">No, no soy de Madrid.</span></p>": "<table><tr><th>Question</th><th>Answer</th></tr>\n <tr><td class=\"es-t\">¿De dónde eres?</td><td class=\"es-t\">Soy de Alemania.</td></tr>\n <tr><td class=\"es-t\">¿De dónde es usted?</td><td class=\"es-t\">Soy de Holanda.</td></tr>\n <tr><td class=\"es-t\">¿Eres de España?</td><td class=\"es-t\">No, soy de Chile.</td></tr>\n <tr><td class=\"es-t\">¿Sois de Colombia?</td><td class=\"es-t\">Sí, de Bogotá.</td></tr>\n <tr><td class=\"es-t\">¿Son ustedes de Madrid?</td><td class=\"es-t\">No, somos de Vigo.</td></tr></table>\n <p><b>Negation:</b> <span class=\"es-t\">no</span> always goes <b>before the verb</b>: <span class=\"es-t\">Messi no es de Barcelona.</span> In answers it's often doubled: <span class=\"es-t\">No, no soy de Madrid.</span></p>", "Länder": "Countries", "Deutschland": "Germany", "Spanien": "Spain", "Österreich": "Austria", "die Schweiz": "Switzerland", "die Niederlande": "the Netherlands", "Frankreich": "France", "Italien": "Italy", "die USA": "the USA", "Mexiko": "Mexico", "Argentinien": "Argentina", "Kolumbien": "Colombia", "Wähle den richtigen Satz:": "Choose the correct sentence:", "<b>no</b> steht direkt vor dem Verb.": "<b>no</b> goes directly before the verb.", "Woher kommen Sie?": "Where are you from? (formal)", "Ich bin aus Deutschland, aus Mannheim.": "I'm from Germany, from Mannheim.", "Seid ihr aus Spanien?": "Are you (all) from Spain?", "Nein, ich bin nicht aus Madrid.": "No, I'm not from Madrid.", "Verben auf -ar & Fragewörter": "Verbs ending in -ar & question words", "Regelmäßige Verben auf -ar": "Regular verbs ending in -ar", "<p>Man streicht <b>-ar</b> und hängt die Endungen an:</p>\n <table><tr><th></th><th>hablar (sprechen)</th><th>Endung</th></tr>\n <tr><td>yo</td><td class=\"es-t\">hablo</td><td>-o</td></tr><tr><td>tú</td><td class=\"es-t\">hablas</td><td>-as</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">habla</td><td>-a</td></tr>\n <tr><td>nosotros/-as</td><td class=\"es-t\">hablamos</td><td>-amos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">habláis</td><td>-áis</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">hablan</td><td>-an</td></tr></table>\n <p>Genauso: <span class=\"es-t\">estudiar, trabajar, buscar, necesitar, usar, practicar, viajar, escuchar, tocar</span>.</p>\n <div class=\"ex\">Betonung auf dem Stamm (<b>ha</b>blo, <b>ha</b>blan) – außer bei nosotros / vosotros (habl<b>a</b>mos, habl<b>áis</b>).</div>": "<p>Drop <b>-ar</b> and add the endings:</p>\n <table><tr><th></th><th>hablar (to speak)</th><th>Ending</th></tr>\n <tr><td>yo</td><td class=\"es-t\">hablo</td><td>-o</td></tr><tr><td>tú</td><td class=\"es-t\">hablas</td><td>-as</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">habla</td><td>-a</td></tr>\n <tr><td>nosotros/-as</td><td class=\"es-t\">hablamos</td><td>-amos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">habláis</td><td>-áis</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">hablan</td><td>-an</td></tr></table>\n <p>The same: <span class=\"es-t\">estudiar, trabajar, buscar, necesitar, usar, practicar, viajar, escuchar, tocar</span>.</p>\n <div class=\"ex\">Stress on the stem (<b>ha</b>blo, <b>ha</b>blan) – except for nosotros / vosotros (habl<b>a</b>mos, habl<b>áis</b>).</div>", "sprechen": "to speak", "studieren / lernen": "to study / to learn", "arbeiten": "to work", "suchen": "to look for", "brauchen": "to need", "benutzen": "to use", "üben / betreiben (Sport)": "to practise / to do (a sport)", "reisen": "to travel", "hören / zuhören": "to listen (to)", "ein Instrument spielen": "to play an instrument", "studieren": "to study", "Spanisch": "Spanish", "Deutsch": "German", "Englisch": "English", "Französisch": "French", "Katalanisch": "Catalan", "Italienisch": "Italian", "Chinesisch": "Chinese", "<table><tr><td class=\"es-t\">¿Qué?</td><td>Was? / Welche?</td><td class=\"es-t\">¿Qué idiomas hablas?</td></tr>\n <tr><td class=\"es-t\">¿Quién? / ¿Quiénes?</td><td>Wer? (Sg. / Pl.)</td><td class=\"es-t\">¿Quiénes estudian chino?</td></tr>\n <tr><td class=\"es-t\">¿Dónde?</td><td>Wo?</td><td class=\"es-t\">¿Dónde trabajas?</td></tr>\n <tr><td class=\"es-t\">¿De dónde?</td><td>Woher?</td><td class=\"es-t\">¿De dónde es Marco?</td></tr>\n <tr><td class=\"es-t\">¿Para qué?</td><td>Wozu?</td><td class=\"es-t\">¿Para qué estudias español?</td></tr>\n <tr><td class=\"es-t\">¿Cómo?</td><td>Wie?</td><td class=\"es-t\">¿Cómo te llamas?</td></tr></table>\n <div class=\"ojo\">Fragewörter tragen <b>immer</b> einen Akzent. Und Fragen beginnen mit <b>¿</b> (Mac: <span class=\"kbd\">⌥ ⇧ ß</span>).</div>": "<table><tr><td class=\"es-t\">¿Qué?</td><td>What? / Which?</td><td class=\"es-t\">¿Qué idiomas hablas?</td></tr>\n <tr><td class=\"es-t\">¿Quién? / ¿Quiénes?</td><td>Who? (sg. / pl.)</td><td class=\"es-t\">¿Quiénes estudian chino?</td></tr>\n <tr><td class=\"es-t\">¿Dónde?</td><td>Where?</td><td class=\"es-t\">¿Dónde trabajas?</td></tr>\n <tr><td class=\"es-t\">¿De dónde?</td><td>Where from?</td><td class=\"es-t\">¿De dónde es Marco?</td></tr>\n <tr><td class=\"es-t\">¿Para qué?</td><td>What for?</td><td class=\"es-t\">¿Para qué estudias español?</td></tr>\n <tr><td class=\"es-t\">¿Cómo?</td><td>How?</td><td class=\"es-t\">¿Cómo te llamas?</td></tr></table>\n <div class=\"ojo\">Question words <b>always</b> carry an accent. And questions start with <b>¿</b> (Mac: <span class=\"kbd\">⌥ ⇧ ?</span>).</div>", "vosotros → <b>-áis</b> (mit Akzent).": "vosotros → <b>-áis</b> (with accent).", "Welche Sprachen sprichst du?": "Which languages do you speak?", "Ich lerne Spanisch, um in Barcelona zu arbeiten.": "I'm learning Spanish to work in Barcelona.", "„um … zu“ = para + Infinitiv": "“in order to” = para + infinitive", "Wo arbeitest du?": "Where do you work?", "Ich brauche Spanisch, um mit meinen Kollegen zu sprechen.": "I need Spanish to talk to my colleagues.", "<table><tr><th>Aussage</th><th>gleiche Meinung</th><th>andere Meinung</th></tr>\n <tr><td class=\"es-t\">Hablo español.</td><td class=\"es-t\">Yo también. <span class=\"muted\">(ich auch)</span></td><td class=\"es-t\">Yo no. <span class=\"muted\">(ich nicht)</span></td></tr>\n <tr><td class=\"es-t\">No hablo francés.</td><td class=\"es-t\">Yo tampoco. <span class=\"muted\">(ich auch nicht)</span></td><td class=\"es-t\">Yo sí. <span class=\"muted\">(ich schon)</span></td></tr></table>\n <div class=\"ex\">Trick: Bei einer <b>positiven</b> Aussage → <i>también / no</i>. Bei einer <b>negativen</b> Aussage → <i>tampoco / sí</i>.</div>\n <p>Im Satz: <span class=\"es-t\">Lucas y Sarah no practican deporte, pero yo sí.</span></p>": "<table><tr><th>Statement</th><th>same opinion</th><th>different opinion</th></tr>\n <tr><td class=\"es-t\">Hablo español.</td><td class=\"es-t\">Yo también. <span class=\"muted\">(me too)</span></td><td class=\"es-t\">Yo no. <span class=\"muted\">(I don't)</span></td></tr>\n <tr><td class=\"es-t\">No hablo francés.</td><td class=\"es-t\">Yo tampoco. <span class=\"muted\">(me neither)</span></td><td class=\"es-t\">Yo sí. <span class=\"muted\">(I do)</span></td></tr></table>\n <div class=\"ex\">Trick: after a <b>positive</b> statement → <i>también / no</i>. After a <b>negative</b> statement → <i>tampoco / sí</i>.</div>\n <p>In a sentence: <span class=\"es-t\">Lucas y Sarah no practican deporte, pero yo sí.</span></p>", "– Trabajo en una empresa. – (Du arbeitest auch.)": "– Trabajo en una empresa. – (You work too.)", "– No hablo chino. – (Du sprichst auch kein Chinesisch.)": "– No hablo chino. – (You don't speak Chinese either.)", "Negative Aussage + gleiche Meinung → <i>tampoco</i>.": "Negative statement + same opinion → <i>tampoco</i>.", "– No practico deporte. – (Du schon!)": "– No practico deporte. – (You do!)", "– Escucho música en español. – (Du nicht.)": "– Escucho música en español. – (You don't.)", "Sprach-Tandem in einer Bar in Gràcia. Du sitzt mit Carla an einem Tisch.": "Language exchange in a bar in Gràcia. You're sitting at a table with Carla.", "Hallo! Wie geht’s? Ich bin Carla. Woher kommst du?": "Hi! How's it going? I'm Carla. Where are you from?", "Herkunft immer mit <b>ser</b>: <i>soy de …</i>": "Origin always with <b>ser</b>: <i>soy de …</i>", "Herkunft: <b>de</b> (aus), nicht <i>en</i> (in).": "Origin: <b>de</b> (from), not <i>en</i> (in).", "Wie schön! Ich bin von hier, aus Barcelona. Welche Sprachen sprichst du?": "How nice! I'm from here, from Barcelona. Which languages do you speak?", "Du sprichst über dich: <i>yo hablo</i>.": "You're talking about yourself: <i>yo hablo</i>.", "Das sind Länder – die Sprachen heißen <i>alemán, inglés</i>.": "Those are countries – the languages are <i>alemán, inglés</i>.", "Ich spreche Katalanisch, Spanisch und Englisch. Ich spreche kein Deutsch.": "I speak Catalan, Spanish and English. I don't speak German.", "Du sprichst kein Katalanisch. Reagiere auf etwas, das ihr gemeinsam habt …": "You don't speak Catalan. React to something you have in common …", "Du sprichst ja kein Katalanisch 😉": "You don't speak Catalan 😉", "„Yo sí“ hieße: Ich spreche schon Deutsch – stimmt zwar, aber du willst über Katalanisch sprechen.": "“Yo sí” would mean: I do speak German – true, but you want to talk about Catalan.", "Haha! Und wozu lernst du Spanisch?": "Haha! And why are you learning Spanish?", "„Um zu“ = <b>para</b> + Infinitiv.": "“In order to” = <b>para</b> + infinitive.", "Nach <b>para</b> kommt der Infinitiv: <i>para estudiar</i>.": "After <b>para</b> comes the infinitive: <i>para estudiar</i>.", "Super! Willkommen in Barcelona.": "Great! Welcome to Barcelona.", "Ich spreche kein Französisch. – Ich auch nicht.": "I don't speak French. – Me neither.", "Sie arbeiten, aber ich nicht.": "They work, but I don't.", "Stell dich in 4–6 Sätzen vor: Name, Herkunft, Wohnort, Sprachen, wozu du Spanisch lernst, was du (nicht) machst.": "Introduce yourself in 4–6 sentences: name, origin, where you live, languages, why you're learning Spanish, what you do (or don't do).", "ser, Verben auf -ar, para + Infinitiv, no/también/tampoco": "ser, verbs ending in -ar, para + infinitive, no/también/tampoco", "Kurze Profile verstehen": "Understanding short profiles", "Profile auf einer Tandem-Plattform. Lies erst ohne Übersetzung.": "Profiles on a language-exchange platform. Read without the translation first.", "Hola, me llamo Núria. Soy de Barcelona y {estudio|ich studiere} Ingeniería Informática en la UPC. Hablo catalán, castellano e inglés. Ahora estudio alemán porque {busco|ich suche} unas prácticas en una empresa de Múnich. Busco una persona para practicar alemán. ¡Yo te ayudo con el español!\n\nMe llamo Tom y soy de Inglaterra. {Trabajo|ich arbeite} en una empresa de turismo en Barcelona. Hablo inglés, francés y un poco de español. Necesito español para hablar por teléfono con los clientes. No hablo catalán, pero quiero aprender un poco.\n\nSomos Ana y Marco, de Italia. Somos estudiantes {de intercambio|Austausch-} en la Universidad de Barcelona. Hablamos italiano e inglés. Buscamos personas para practicar español los {fines de semana|Wochenenden}. También {tocamos|wir spielen} la guitarra.": "Hola, me llamo Núria. Soy de Barcelona y {estudio|I study} Ingeniería Informática en la UPC. Hablo catalán, castellano e inglés. Ahora estudio alemán porque {busco|I'm looking for} unas prácticas en una empresa de Múnich. Busco una persona para practicar alemán. ¡Yo te ayudo con el español!\n\nMe llamo Tom y soy de Inglaterra. {Trabajo|I work} en una empresa de turismo en Barcelona. Hablo inglés, francés y un poco de español. Necesito español para hablar por teléfono con los clientes. No hablo catalán, pero quiero aprender un poco.\n\nSomos Ana y Marco, de Italia. Somos estudiantes {de intercambio|exchange} en la Universidad de Barcelona. Hablamos italiano e inglés. Buscamos personas para practicar español los {fines de semana|weekends}. También {tocamos|we play} la guitarra.", "Hallo, ich heiße Núria. Ich bin aus Barcelona und studiere Informatik an der UPC. Ich spreche Katalanisch, Spanisch und Englisch. Jetzt lerne ich Deutsch, weil ich ein Praktikum in einer Firma in München suche. Ich suche jemanden, um Deutsch zu üben. Ich helfe dir mit dem Spanischen!\n\nIch heiße Tom und komme aus England. Ich arbeite bei einer Tourismusfirma in Barcelona. Ich spreche Englisch, Französisch und ein bisschen Spanisch. Ich brauche Spanisch, um mit den Kunden zu telefonieren. Ich spreche kein Katalanisch, aber ich will ein bisschen lernen.\n\nWir sind Ana und Marco aus Italien. Wir sind Austauschstudenten an der Universität Barcelona. Wir sprechen Italienisch und Englisch. Wir suchen Leute, um am Wochenende Spanisch zu üben. Wir spielen auch Gitarre.": "Hi, my name is Núria. I'm from Barcelona and I study Computer Engineering at the UPC. I speak Catalan, Spanish and English. Now I'm learning German because I'm looking for an internship at a company in Munich. I'm looking for someone to practise German with. I'll help you with your Spanish!\n\nMy name is Tom and I'm from England. I work for a tourism company in Barcelona. I speak English, French and a little Spanish. I need Spanish to talk to customers on the phone. I don't speak Catalan, but I want to learn a little.\n\nWe're Ana and Marco from Italy. We're exchange students at the University of Barcelona. We speak Italian and English. We're looking for people to practise Spanish with at the weekends. We also play the guitar.", "Für wen wäre Jonas der perfekte Tandempartner?": "Who would be the perfect tandem partner for a German speaker?", "Núria – sie lernt Deutsch.": "Núria – she's learning German.", "Tom – er lernt Französisch.": "Tom – he's learning French.", "Schreib dein eigenes Profil für die Bolsa de intercambio (4–5 Sätze).": "Write your own profile for the Bolsa de intercambio (4–5 sentences).", "ser, -ar-Verben, para + Infinitiv": "ser, -ar verbs, para + infinitive", "<h3>Substantive & Artikel</h3><table><tr><th></th><th>männlich</th><th>weiblich</th></tr><tr><td>Sg.</td><td class=\"es-t\">el / un producto</td><td class=\"es-t\">la / una empresa</td></tr><tr><td>Pl.</td><td class=\"es-t\">los / unos productos</td><td class=\"es-t\">las / unas empresas</td></tr></table>\n<p>-o → meist m · -a, -dad, -ción → meist w · Ausnahmen: el día, el programa, la foto. Plural: Vokal + s, Konsonant + es.</p>\n<h3>ser</h3><table><tr><td>soy · eres · es</td><td>somos · sois · son</td></tr></table>\n<h3>Verben auf -ar (hablar)</h3><table><tr><td>hablo · hablas · habla</td><td>hablamos · habláis · hablan</td></tr></table>\n<h3>Herkunft</h3><table><tr><td class=\"es-t\">¿De dónde eres?</td><td class=\"es-t\">Soy de Alemania.</td></tr><tr><td class=\"es-t\">¿Eres de España?</td><td class=\"es-t\">No, soy de Chile.</td></tr></table>\n<h3>Fragewörter</h3><p class=\"es-t\">¿Qué? · ¿Quién/es? · ¿Dónde? · ¿De dónde? · ¿Para qué? · ¿Cómo?</p>\n<h3>Zustimmung & Widerspruch</h3><table><tr><td class=\"es-t\">Hablo español.</td><td class=\"es-t\">Yo también. / Yo no.</td></tr><tr><td class=\"es-t\">No hablo francés.</td><td class=\"es-t\">Yo tampoco. / Yo sí.</td></tr></table>\n<h3>Zahlen 0–10</h3><p class=\"es-t\">cero, uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez</p>": "<h3>Nouns & articles</h3><table><tr><th></th><th>masculine</th><th>feminine</th></tr><tr><td>sg.</td><td class=\"es-t\">el / un producto</td><td class=\"es-t\">la / una empresa</td></tr><tr><td>pl.</td><td class=\"es-t\">los / unos productos</td><td class=\"es-t\">las / unas empresas</td></tr></table>\n<p>-o → usually m · -a, -dad, -ción → usually f · exceptions: el día, el programa, la foto. Plural: vowel + s, consonant + es.</p>\n<h3>ser</h3><table><tr><td>soy · eres · es</td><td>somos · sois · son</td></tr></table>\n<h3>Verbs ending in -ar (hablar)</h3><table><tr><td>hablo · hablas · habla</td><td>hablamos · habláis · hablan</td></tr></table>\n<h3>Origin</h3><table><tr><td class=\"es-t\">¿De dónde eres?</td><td class=\"es-t\">Soy de Alemania.</td></tr><tr><td class=\"es-t\">¿Eres de España?</td><td class=\"es-t\">No, soy de Chile.</td></tr></table>\n<h3>Question words</h3><p class=\"es-t\">¿Qué? · ¿Quién/es? · ¿Dónde? · ¿De dónde? · ¿Para qué? · ¿Cómo?</p>\n<h3>Agreeing & disagreeing</h3><table><tr><td class=\"es-t\">Hablo español.</td><td class=\"es-t\">Yo también. / Yo no.</td></tr><tr><td class=\"es-t\">No hablo francés.</td><td class=\"es-t\">Yo tampoco. / Yo sí.</td></tr></table>\n<h3>Numbers 0–10</h3><p class=\"es-t\">cero, uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez</p>", "Jemanden vorstellen · buchstabieren · Alter · Telefon & E-Mail · Studium & Beruf · Tätigkeiten beschreiben": "Introducing someone · spelling · age · phone & e-mail · studies & job · describing tasks", "Alphabet & buchstabieren": "Alphabet & spelling", "Berufe (m/w)": "Jobs (m/f)", "Zahlen ab 11": "Numbers from 11", "tener + Alter": "tener + age", "Telefon, E-Mail, Adresse": "Phone, e-mail, address", "Verben auf -er / -ir": "Verbs ending in -er / -ir", "Networking auf einer Tech-Messe": "Networking at a tech fair", "Du bist auf einer Tech-Messe in der Fira de Barcelona (Montjuïc) und suchst ein Praktikum. Am Stand einer Firma spricht dich eine Recruiterin an.": "You're at a tech fair at the Fira de Barcelona (Montjuïc) looking for an internship. At a company's stand a recruiter starts talking to you.", "Stell dich vor, sag, was du studierst und wo du gearbeitet hast (EY, Wirtschaftsprüfung/IT), und gib deine Handynummer und E-Mail-Adresse (buchstabieren!) an.": "Introduce yourself, say what you study and where you've worked (EY, auditing/IT), and give your mobile number and e-mail address (spell it!).", "<p>Um jemanden vorzustellen, benutzt man <b>Demonstrativpronomen</b> (dies/das ist …):</p>\n <table><tr><th></th><th>männlich</th><th>weiblich</th></tr>\n <tr><td>Singular</td><td class=\"es-t\">Este es el señor Vega.</td><td class=\"es-t\">Esta es Paula Díaz.</td></tr>\n <tr><td>Plural</td><td class=\"es-t\">Estos son Andrés y Pablo.</td><td class=\"es-t\">Estas son Ana y Elena.</td></tr></table>\n <p>Antwort: <span class=\"es-t\">Encantado</span> (Mann spricht) / <span class=\"es-t\">Encantada</span> (Frau spricht) / <span class=\"es-t\">Mucho gusto</span> (alle).</p>\n <div class=\"ojo\">Gemischte Gruppe → männliche Form: <span class=\"es-t\">Estos son Laia y Marc.</span></div>": "<p>To introduce someone you use <b>demonstrative pronouns</b> (this is …):</p>\n <table><tr><th></th><th>masculine</th><th>feminine</th></tr>\n <tr><td>Singular</td><td class=\"es-t\">Este es el señor Vega.</td><td class=\"es-t\">Esta es Paula Díaz.</td></tr>\n <tr><td>Plural</td><td class=\"es-t\">Estos son Andrés y Pablo.</td><td class=\"es-t\">Estas son Ana y Elena.</td></tr></table>\n <p>Answer: <span class=\"es-t\">Encantado</span> (a man speaking) / <span class=\"es-t\">Encantada</span> (a woman speaking) / <span class=\"es-t\">Mucho gusto</span> (everyone).</p>\n <div class=\"ojo\">Mixed group → masculine form: <span class=\"es-t\">Estos son Laia y Marc.</span></div>", "Du stellst deine Mitbewohnerin Núria vor:": "You introduce your flatmate Núria:", "Du stellst zwei Kommilitonen vor, Marc und Laia:": "You introduce two fellow students, Marc and Laia:", "Gemischte Gruppe → <i>estos</i>.": "Mixed group → <i>estos</i>.", "Pablo ist ein Mann → <i>este</i>. Marta spricht → <i>encantada</i>.": "Pablo is a man → <i>este</i>. Marta is speaking → <i>encantada</i>.", "<table><tr><td>a <span class=\"es-t\">a</span></td><td>b <span class=\"es-t\">be</span></td><td>c <span class=\"es-t\">ce</span></td><td>d <span class=\"es-t\">de</span></td><td>e <span class=\"es-t\">e</span></td><td>f <span class=\"es-t\">efe</span></td><td>g <span class=\"es-t\">ge</span></td></tr>\n <tr><td>h <span class=\"es-t\">hache</span></td><td>i <span class=\"es-t\">i</span></td><td>j <span class=\"es-t\">jota</span></td><td>k <span class=\"es-t\">ka</span></td><td>l <span class=\"es-t\">ele</span></td><td>m <span class=\"es-t\">eme</span></td><td>n <span class=\"es-t\">ene</span></td></tr>\n <tr><td>ñ <span class=\"es-t\">eñe</span></td><td>o <span class=\"es-t\">o</span></td><td>p <span class=\"es-t\">pe</span></td><td>q <span class=\"es-t\">cu</span></td><td>r <span class=\"es-t\">erre</span></td><td>s <span class=\"es-t\">ese</span></td><td>t <span class=\"es-t\">te</span></td></tr>\n <tr><td>u <span class=\"es-t\">u</span></td><td>v <span class=\"es-t\">uve</span></td><td>w <span class=\"es-t\">uve doble</span></td><td>x <span class=\"es-t\">equis</span></td><td>y <span class=\"es-t\">i griega</span></td><td>z <span class=\"es-t\">zeta</span></td><td></td></tr></table>\n <table><tr><td class=\"es-t\">¿Cómo se escribe?</td><td>Wie schreibt man das?</td></tr><tr><td class=\"es-t\">¿Se escribe con hache?</td><td>Schreibt man das mit h?</td></tr>\n <tr><td class=\"es-t\">¿Con acento o sin acento?</td><td>Mit oder ohne Akzent?</td></tr><tr><td class=\"es-t\">¿Con mayúscula?</td><td>Groß geschrieben?</td></tr></table>": "<table><tr><td>a <span class=\"es-t\">a</span></td><td>b <span class=\"es-t\">be</span></td><td>c <span class=\"es-t\">ce</span></td><td>d <span class=\"es-t\">de</span></td><td>e <span class=\"es-t\">e</span></td><td>f <span class=\"es-t\">efe</span></td><td>g <span class=\"es-t\">ge</span></td></tr>\n <tr><td>h <span class=\"es-t\">hache</span></td><td>i <span class=\"es-t\">i</span></td><td>j <span class=\"es-t\">jota</span></td><td>k <span class=\"es-t\">ka</span></td><td>l <span class=\"es-t\">ele</span></td><td>m <span class=\"es-t\">eme</span></td><td>n <span class=\"es-t\">ene</span></td></tr>\n <tr><td>ñ <span class=\"es-t\">eñe</span></td><td>o <span class=\"es-t\">o</span></td><td>p <span class=\"es-t\">pe</span></td><td>q <span class=\"es-t\">cu</span></td><td>r <span class=\"es-t\">erre</span></td><td>s <span class=\"es-t\">ese</span></td><td>t <span class=\"es-t\">te</span></td></tr>\n <tr><td>u <span class=\"es-t\">u</span></td><td>v <span class=\"es-t\">uve</span></td><td>w <span class=\"es-t\">uve doble</span></td><td>x <span class=\"es-t\">equis</span></td><td>y <span class=\"es-t\">i griega</span></td><td>z <span class=\"es-t\">zeta</span></td><td></td></tr></table>\n <table><tr><td class=\"es-t\">¿Cómo se escribe?</td><td>How do you spell that?</td></tr><tr><td class=\"es-t\">¿Se escribe con hache?</td><td>Is it spelled with an h?</td></tr>\n <tr><td class=\"es-t\">¿Con acento o sin acento?</td><td>With or without an accent?</td></tr><tr><td class=\"es-t\">¿Con mayúscula?</td><td>With a capital letter?</td></tr></table>", "das ist … (m / w)": "this is … (m / f)", "freut mich": "nice to meet you", "Wie schreibt man das?": "How do you spell that?", "der Nachname": "the surname", "der Vorname / Name": "the first name / name", "mit / ohne Akzent": "with / without an accent", "Groß- / Kleinbuchstabe": "capital / small letter", "Hör zu: Welcher Name wird buchstabiert? Schreib die Buchstabennamen ab (z. B. „jota, o, …“).": "Listen: which name is being spelled? Write down the letter names (e.g. “jota, o, …”).", "Wie buchstabiert man „G“ auf Spanisch?": "How do you spell “G” in Spanish?", "G = <i>ge</i> (gesprochen wie „che“), J = <i>jota</i>.": "G = <i>ge</i> (pronounced like “heh”), J = <i>jota</i>.", "„Gross“ – du sagst, dass man das Doppel-S mit zwei S schreibt. Wie heißt der Buchstabe S?": "“Gross” – you say that the double S is written with two S's. What's the letter S called?", "Wie schreibt man deinen Nachnamen?": "How do you spell your surname?", "Deinen Nachnamen buchstabieren": "Spelling your surname", "Berufsbezeichnungen: männlich & weiblich": "Job titles: masculine & feminine", "<table><tr><th>Regel</th><th>männlich</th><th>weiblich</th></tr>\n <tr><td>-o → -a</td><td class=\"es-t\">ingeniero, médico, informático</td><td class=\"es-t\">ingeniera, médica, informática</td></tr>\n <tr><td>-or → -ora</td><td class=\"es-t\">profesor, programador, diseñador</td><td class=\"es-t\">profesora, programadora, diseñadora</td></tr>\n <tr><td>-e, -ista, Konsonant: gleich</td><td class=\"es-t\">el estudiante, el analista</td><td class=\"es-t\">la estudiante, la analista</td></tr></table>\n <div class=\"ojo\"><span class=\"es-t\">el jefe / la jefa</span> – Ausnahme. Und: Bei Berufen <b>kein Artikel</b>: <span class=\"es-t\">Soy ingeniero.</span> (nicht „soy un ingeniero“)</div>": "<table><tr><th>Rule</th><th>masculine</th><th>feminine</th></tr>\n <tr><td>-o → -a</td><td class=\"es-t\">ingeniero, médico, informático</td><td class=\"es-t\">ingeniera, médica, informática</td></tr>\n <tr><td>-or → -ora</td><td class=\"es-t\">profesor, programador, diseñador</td><td class=\"es-t\">profesora, programadora, diseñadora</td></tr>\n <tr><td>-e, -ista, consonant: the same</td><td class=\"es-t\">el estudiante, el analista</td><td class=\"es-t\">la estudiante, la analista</td></tr></table>\n <div class=\"ojo\"><span class=\"es-t\">el jefe / la jefa</span> – an exception. And: with jobs <b>no article</b>: <span class=\"es-t\">Soy ingeniero.</span> (not “soy un ingeniero”)</div>", "Ingenieur/in": "engineer", "Informatiker/in": "IT specialist / computer scientist", "Programmierer/in": "programmer", "Analyst/in": "analyst", "Wirtschaftsprüfer/in": "auditor", "Berater/in": "consultant", "Student/in": "student", "Lehrer/in, Dozent/in": "teacher, lecturer", "Arzt / Ärztin": "doctor", "Designer/in": "designer", "Rezeptionist/in": "receptionist", "Chef/in": "boss", "Weibliche Form:": "Feminine form:", "-ista bleibt gleich.": "-ista stays the same.", "Wie sagst du „Ich bin Student“?": "How do you say “I'm a student”?", "Beruf: <b>ser</b> ohne Artikel.": "Job: <b>ser</b> without an article.", "Wer macht was?": "Who does what?", "Laia ist Ingenieurin.": "Laia is an engineer.", "Ich bin Informatiker.": "I'm an IT specialist.", "<table><tr><td class=\"es-t\">21 veintiuno</td><td class=\"es-t\">22 veintidós</td><td class=\"es-t\">23 veintitrés</td><td class=\"es-t\">29 veintinueve</td></tr>\n <tr><td class=\"es-t\">30 treinta</td><td class=\"es-t\">31 treinta y uno</td><td class=\"es-t\">40 cuarenta</td><td class=\"es-t\">50 cincuenta</td></tr>\n <tr><td class=\"es-t\">60 sesenta</td><td class=\"es-t\">70 setenta</td><td class=\"es-t\">80 ochenta</td><td class=\"es-t\">90 noventa</td></tr>\n <tr><td class=\"es-t\">100 cien</td><td class=\"es-t\">101 ciento uno</td><td class=\"es-t\">200 doscientos</td><td class=\"es-t\">500 quinientos</td></tr>\n <tr><td class=\"es-t\">1000 mil</td><td class=\"es-t\">2000 dos mil</td><td class=\"es-t\">2026 dos mil veintiséis</td><td></td></tr></table>\n <div class=\"ex\">Bis 29 in einem Wort (veinti…), ab 31 mit <b>y</b>: <span class=\"es-t\">treinta y cinco</span>. Genau 100 = <span class=\"es-t\">cien</span>, danach <span class=\"es-t\">ciento</span>.</div>": "<table><tr><td class=\"es-t\">21 veintiuno</td><td class=\"es-t\">22 veintidós</td><td class=\"es-t\">23 veintitrés</td><td class=\"es-t\">29 veintinueve</td></tr>\n <tr><td class=\"es-t\">30 treinta</td><td class=\"es-t\">31 treinta y uno</td><td class=\"es-t\">40 cuarenta</td><td class=\"es-t\">50 cincuenta</td></tr>\n <tr><td class=\"es-t\">60 sesenta</td><td class=\"es-t\">70 setenta</td><td class=\"es-t\">80 ochenta</td><td class=\"es-t\">90 noventa</td></tr>\n <tr><td class=\"es-t\">100 cien</td><td class=\"es-t\">101 ciento uno</td><td class=\"es-t\">200 doscientos</td><td class=\"es-t\">500 quinientos</td></tr>\n <tr><td class=\"es-t\">1000 mil</td><td class=\"es-t\">2000 dos mil</td><td class=\"es-t\">2026 dos mil veintiséis</td><td></td></tr></table>\n <div class=\"ex\">Up to 29 written as one word (veinti…), from 31 with <b>y</b>: <span class=\"es-t\">treinta y cinco</span>. Exactly 100 = <span class=\"es-t\">cien</span>, after that <span class=\"es-t\">ciento</span>.</div>", "Schreib die Zahl als Wort.": "Write the number as a word.", "Alter mit tener": "Age with tener", "<table><tr><th>tener (haben)</th><th></th></tr><tr><td>yo</td><td class=\"es-t\">tengo</td></tr><tr><td>tú</td><td class=\"es-t\">tienes</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">tiene</td></tr><tr><td>nosotros/-as</td><td class=\"es-t\">tenemos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">tenéis</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">tienen</td></tr></table>\n <div class=\"ojo\">Das Alter „hat“ man: <span class=\"es-t\">Tengo 23 años.</span> – nicht „soy 23“! Frage: <span class=\"es-t\">¿Cuántos años tienes?</span></div>": "<table><tr><th>tener (to have)</th><th></th></tr><tr><td>yo</td><td class=\"es-t\">tengo</td></tr><tr><td>tú</td><td class=\"es-t\">tienes</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">tiene</td></tr><tr><td>nosotros/-as</td><td class=\"es-t\">tenemos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">tenéis</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">tienen</td></tr></table>\n <div class=\"ojo\">In Spanish you “have” your age: <span class=\"es-t\">Tengo 23 años.</span> – not “soy 23”! Question: <span class=\"es-t\">¿Cuántos años tienes?</span></div>", "haben": "to have", "<table><tr><td class=\"es-t\">¿Cuál es tu (número de) móvil?</td><td class=\"es-t\">Es el 612 34 56 78.</td></tr>\n <tr><td class=\"es-t\">¿Cuál es tu correo electrónico?</td><td class=\"es-t\">Es jonas.gross@web.de</td></tr>\n <tr><td class=\"es-t\">¿Cuál es tu dirección?</td><td class=\"es-t\">Calle Mallorca, número 40.</td></tr></table>\n <table><tr><td><b>@</b> <span class=\"es-t\">arroba</span></td><td><b>.</b> <span class=\"es-t\">punto</span></td><td><b>-</b> <span class=\"es-t\">guion</span></td><td><b>_</b> <span class=\"es-t\">guion bajo</span></td></tr>\n <tr><td><span class=\"es-t\">c/</span> = calle</td><td><span class=\"es-t\">av.</span> = avenida</td><td><span class=\"es-t\">pl.</span> = plaza</td><td><span class=\"es-t\">n.º</span> = número</td></tr></table>\n <div class=\"ex\">Telefonnummern liest man in Spanien meist in Paaren oder Dreiergruppen: <span class=\"es-t\">seis uno dos, treinta y cuatro, cincuenta y seis, setenta y ocho</span>.</div>": "<table><tr><td class=\"es-t\">¿Cuál es tu (número de) móvil?</td><td class=\"es-t\">Es el 612 34 56 78.</td></tr>\n <tr><td class=\"es-t\">¿Cuál es tu correo electrónico?</td><td class=\"es-t\">Es jonas.gross@web.de</td></tr>\n <tr><td class=\"es-t\">¿Cuál es tu dirección?</td><td class=\"es-t\">Calle Mallorca, número 40.</td></tr></table>\n <table><tr><td><b>@</b> <span class=\"es-t\">arroba</span></td><td><b>.</b> <span class=\"es-t\">punto</span></td><td><b>-</b> <span class=\"es-t\">guion</span></td><td><b>_</b> <span class=\"es-t\">guion bajo</span></td></tr>\n <tr><td><span class=\"es-t\">c/</span> = calle</td><td><span class=\"es-t\">av.</span> = avenida</td><td><span class=\"es-t\">pl.</span> = plaza</td><td><span class=\"es-t\">n.º</span> = número</td></tr></table>\n <div class=\"ex\">In Spain phone numbers are usually read in pairs or groups of three: <span class=\"es-t\">seis uno dos, treinta y cuatro, cincuenta y seis, setenta y ocho</span>.</div>", "das Handy": "the mobile phone", "die E-Mail": "the e-mail", "die Adresse": "the address", "die Straße": "the street", "Punkt": "dot", "Bindestrich": "hyphen", "Wie alt bist du?": "How old are you?", "Wie liest man „laia_p@gmail.com“?": "How do you read “laia_p@gmail.com”?", "Ich bin 24 Jahre alt.": "I'm 24 years old.", "Wie ist deine Handynummer?": "What's your mobile number?", "Verben auf -er/-ir · Studium & Beruf": "Verbs ending in -er/-ir · studies & job", "Regelmäßige Verben auf -er und -ir": "Regular verbs ending in -er and -ir", "<table><tr><th></th><th>aprender (lernen)</th><th>vivir (leben, wohnen)</th></tr>\n <tr><td>yo</td><td class=\"es-t\">aprendo</td><td class=\"es-t\">vivo</td></tr><tr><td>tú</td><td class=\"es-t\">aprendes</td><td class=\"es-t\">vives</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">aprende</td><td class=\"es-t\">vive</td></tr>\n <tr><td>nosotros/-as</td><td class=\"es-t\">aprendemos</td><td class=\"es-t\">vivimos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">aprendéis</td><td class=\"es-t\">vivís</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">aprenden</td><td class=\"es-t\">viven</td></tr></table>\n <div class=\"ex\">-er und -ir unterscheiden sich nur bei <b>nosotros</b> (-emos / -imos) und <b>vosotros</b> (-éis / -ís).</div>\n <p>Genauso: <span class=\"es-t\">leer, comer, beber, responder · escribir, asistir, abrir</span>.</p>": "<table><tr><th></th><th>aprender (to learn)</th><th>vivir (to live)</th></tr>\n <tr><td>yo</td><td class=\"es-t\">aprendo</td><td class=\"es-t\">vivo</td></tr><tr><td>tú</td><td class=\"es-t\">aprendes</td><td class=\"es-t\">vives</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">aprende</td><td class=\"es-t\">vive</td></tr>\n <tr><td>nosotros/-as</td><td class=\"es-t\">aprendemos</td><td class=\"es-t\">vivimos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">aprendéis</td><td class=\"es-t\">vivís</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">aprenden</td><td class=\"es-t\">viven</td></tr></table>\n <div class=\"ex\">-er and -ir only differ for <b>nosotros</b> (-emos / -imos) and <b>vosotros</b> (-éis / -ís).</div>\n <p>The same: <span class=\"es-t\">leer, comer, beber, responder · escribir, asistir, abrir</span>.</p>", "wohnen, leben": "to live", "lernen": "to learn", "Über Studium und Beruf sprechen": "Talking about studies and work", "Was machst du (beruflich)?": "What do you do (for a living)?", "als … arbeiten": "to work as …", "die Beratungsfirma": "the consulting firm", "die Bank": "the bank", "die Universität": "the university", "der Master": "the master's degree", "das Praktikum": "the internship", "schreiben": "to write", "lesen": "to read", "das Stadtviertel": "the neighbourhood", "Ich arbeite als Prüfer in einem internationalen Unternehmen.": "I work as an auditor at an international company.", "Anmeldung im Fitnessstudio": "Signing up at the gym", "Du meldest dich in einem Fitnessstudio an. Der Mitarbeiter füllt ein Formular aus.": "You're signing up at a gym. The employee fills in a form.", "Hallo, guten Tag. Dein Name, bitte?": "Hello, good afternoon. Your name, please?", "Name: <i>Soy / Me llamo …</i> oder einfach nur der Name.": "Name: <i>Soy / Me llamo …</i> or simply the name.", "Perfekt. Wie alt bist du?": "Perfect. How old are you?", "Alter immer mit <b>tener</b>: <i>tengo … años</i>.": "Age always with <b>tener</b>: <i>tengo … años</i>.", "Über dich selbst: <i>tengo</i>.": "About yourself: <i>tengo</i>.", "Und was machst du beruflich?": "And what do you do for a living?", "Bei Berufen kein Artikel: <i>Soy estudiante</i>.": "With jobs no article: <i>Soy estudiante</i>.", "Ah! Wir haben Studentenrabatt. Und deine E-Mail?": "Ah! We have a student discount. And your e-mail?", "„.“ = <i>punto</i>, „@“ = <i>arroba</i>.": "“.” = <i>punto</i>, “@” = <i>arroba</i>.", "Sehr gut. Willkommen!": "Very good. Welcome!", "Wo wohnst du?": "Where do you live?", "Ich studiere Informatik in Barcelona.": "I study computer science in Barcelona.", "Tätigkeiten beschreiben": "Describing tasks", "Tätigkeiten im Job": "Tasks at work", "die Buchhaltung führen": "to do the bookkeeping", "den Terminkalender führen": "to manage the diary / schedule", "Seminare organisieren": "to organise seminars", "Messen und Kongresse besuchen": "to attend trade fairs and conferences", "die E-Mails beantworten": "to answer the e-mails", "verantwortlich sein für …": "to be responsible for …", "Kunden kontaktieren": "to contact customers", "der Kunde / die Kundin": "the client / customer", "die Abteilung": "the department", "prüfen, überprüfen": "to check, to review", "<p>Wenn <b>de</b> und <b>el</b> zusammentreffen, verschmelzen sie zu <b>del</b> (ähnlich wie „von dem“ → „vom“):</p>\n <table><tr><td class=\"es-t\">Es responsable del contacto con clientes.</td><td>de + el</td></tr>\n <tr><td class=\"es-t\">Es responsable de la agenda.</td><td>bleibt</td></tr>\n <tr><td class=\"es-t\">Es responsable de los empleados.</td><td>bleibt</td></tr>\n <tr><td class=\"es-t\">Es responsable de las empresas.</td><td>bleibt</td></tr></table>\n <div class=\"ojo\">Nur <b>de + el</b> verschmilzt. Später lernst du auch <b>a + el = al</b>.</div>": "<p>When <b>de</b> and <b>el</b> meet, they merge into <b>del</b> (“of the”):</p>\n <table><tr><td class=\"es-t\">Es responsable del contacto con clientes.</td><td>de + el</td></tr>\n <tr><td class=\"es-t\">Es responsable de la agenda.</td><td>stays</td></tr>\n <tr><td class=\"es-t\">Es responsable de los empleados.</td><td>stays</td></tr>\n <tr><td class=\"es-t\">Es responsable de las empresas.</td><td>stays</td></tr></table>\n <div class=\"ojo\">Only <b>de + el</b> merges. Later you'll also learn <b>a + el = al</b>.</div>", "Was macht jemand, der „lleva la contabilidad“?": "What does someone do who “lleva la contabilidad”?", "die Buchhaltung": "the bookkeeping", "den Terminkalender": "the diary / schedule", "die Webseite": "the website", "Ich bin verantwortlich für den Kontakt mit Kunden.": "I'm responsible for contact with customers.", "Beschreibe in 4–6 Sätzen deine Arbeit bei EY (oder einen Job, den du dir wünschst): Was machst du, wo, wofür bist du verantwortlich, mit wem sprichst du?": "Describe your job at EY (or a job you'd like) in 4–6 sentences: what do you do, where, what are you responsible for, who do you talk to?", "Verben auf -ar/-er/-ir, Berufe, ser responsable de, del": "verbs ending in -ar/-er/-ir, jobs, ser responsable de, del", "Ein berufliches Profil verstehen": "Understanding a professional profile", "Ein Profil auf einem beruflichen Netzwerk.": "A profile on a professional network.", "Me llamo Marta Vidal Roca y tengo 29 años. Vivo en Barcelona, en el barrio de Poblenou. Soy ingeniera {informática|Informatik-} y trabajo como {analista de ciberseguridad|Cybersecurity-Analystin} en una consultora internacional.\n\nEn mi trabajo {reviso|ich prüfe} los sistemas de los clientes y escribo {informes|Berichte}. Soy responsable del contacto con dos clientes del sector bancario. También organizo seminarios para los nuevos empleados y a veces asisto a congresos.\n\nHablo catalán, castellano, inglés y un poco de francés. Ahora aprendo alemán porque mi empresa tiene {una sede|einen Standort} en Fráncfort. Mi correo electrónico es marta.vidal arroba consultora punto es.": "Me llamo Marta Vidal Roca y tengo 29 años. Vivo en Barcelona, en el barrio de Poblenou. Soy ingeniera {informática|computer} y trabajo como {analista de ciberseguridad|cybersecurity analyst} en una consultora internacional.\n\nEn mi trabajo {reviso|I check} los sistemas de los clientes y escribo {informes|reports}. Soy responsable del contacto con dos clientes del sector bancario. También organizo seminarios para los nuevos empleados y a veces asisto a congresos.\n\nHablo catalán, castellano, inglés y un poco de francés. Ahora aprendo alemán porque mi empresa tiene {una sede|an office} en Fráncfort. Mi correo electrónico es marta.vidal arroba consultora punto es.", "Ich heiße Marta Vidal Roca und bin 29 Jahre alt. Ich wohne in Barcelona, im Viertel Poblenou. Ich bin Informatik-Ingenieurin und arbeite als Cybersecurity-Analystin bei einer internationalen Beratung.\n\nIn meiner Arbeit prüfe ich die Systeme der Kunden und schreibe Berichte. Ich bin verantwortlich für den Kontakt mit zwei Kunden aus dem Bankensektor. Ich organisiere auch Seminare für die neuen Angestellten und besuche manchmal Kongresse.\n\nIch spreche Katalanisch, Spanisch, Englisch und ein bisschen Französisch. Jetzt lerne ich Deutsch, weil meine Firma einen Standort in Frankfurt hat. Meine E-Mail-Adresse ist marta.vidal@consultora.es.": "My name is Marta Vidal Roca and I'm 29. I live in Barcelona, in the Poblenou neighbourhood. I'm a computer engineer and I work as a cybersecurity analyst at an international consultancy.\n\nIn my job I check the clients' systems and write reports. I'm responsible for contact with two clients from the banking sector. I also organise seminars for new employees and sometimes attend conferences.\n\nI speak Catalan, Spanish, English and a little French. Now I'm learning German because my company has an office in Frankfurt. My e-mail address is marta.vidal@consultora.es.", "Schreib Martas E-Mail-Adresse.": "Write Marta's e-mail address.", "📎 Übungsblatt: ¿Qué hacen ahora?": "📎 Worksheet: ¿Qué hacen ahora?", "Aus deinem Kurs (Semester 3) · Berufe, ser, Verben auf -ar/-er/-ir": "From a university Spanish course (semester 3) · jobs, ser, verbs ending in -ar/-er/-ir", "Alberto und Raúl schauen sich ein altes Klassenfoto an.": "Alberto and Raúl are looking at an old class photo.", "Alberto: ¡Veinticinco años ya! ¿Y qué hacen ahora?\nRaúl: Pues, Ana trabaja en un {instituto|Gymnasium}, es profesora de inglés en Granada. José Luis vive aquí, en Barcelona. Es cocinero, pero ahora no tiene trabajo.\n\nAlberto: ¡Qué {lástima|schade}! Y Juan y tú, ¿trabajáis todavía en el Banco de Santander?\nRaúl: Yo sí, pero Juan trabaja ahora en el Banco Atlántico. Es jefe del departamento de créditos.\n\nAlberto: ¡Qué bien! Y Carmen, mi ex-novia, ¿qué hace?\nRaúl: Carmen vive en Toledo y es {ama de casa|Hausfrau}. Tiene tres hijos que estudian en la universidad.\n\nAlberto: ¡No me digas! Y Pepe también vive en Toledo, ¿verdad?\nRaúl: Sí, está {casado|verheiratet} con una colombiana. Los dos son médicos y trabajan en un hospital.": "Alberto: ¡Veinticinco años ya! ¿Y qué hacen ahora?\nRaúl: Pues, Ana trabaja en un {instituto|secondary school}, es profesora de inglés en Granada. José Luis vive aquí, en Barcelona. Es cocinero, pero ahora no tiene trabajo.\n\nAlberto: ¡Qué {lástima|pity}! Y Juan y tú, ¿trabajáis todavía en el Banco de Santander?\nRaúl: Yo sí, pero Juan trabaja ahora en el Banco Atlántico. Es jefe del departamento de créditos.\n\nAlberto: ¡Qué bien! Y Carmen, mi ex-novia, ¿qué hace?\nRaúl: Carmen vive en Toledo y es {ama de casa|housewife}. Tiene tres hijos que estudian en la universidad.\n\nAlberto: ¡No me digas! Y Pepe también vive en Toledo, ¿verdad?\nRaúl: Sí, está {casado|married} con una colombiana. Los dos son médicos y trabajan en un hospital.", "Übungsblatt": "Worksheet", "<p>Julia und Paul aus Köln sind im Urlaub in Argentinien und treffen einen Herrn aus Buenos Aires:</p>\n <div class=\"ex\"><span class=\"es-t\">Señor: Perdón, ustedes no son argentinos, ¿verdad?</span><br><span class=\"es-t\">Julia: No, no. Somos alemanes.</span><br><span class=\"es-t\">Señor: ¿Aprenden español en Alemania?</span><br><span class=\"es-t\">Julia: Sí, en la Universidad Popular.</span><br><span class=\"es-t\">Paul: Yo trabajo en una empresa que vende tractores y ella escribe para un periódico.</span><br><span class=\"es-t\">Señor: Yo vivo en Buenos Aires. Trabajo en una agencia de viajes.</span></div>": "<p>Julia and Paul from Cologne are on holiday in Argentina and meet a gentleman from Buenos Aires:</p>\n <div class=\"ex\"><span class=\"es-t\">Señor: Perdón, ustedes no son argentinos, ¿verdad?</span><br><span class=\"es-t\">Julia: No, no. Somos alemanes.</span><br><span class=\"es-t\">Señor: ¿Aprenden español en Alemania?</span><br><span class=\"es-t\">Julia: Sí, en la Universidad Popular.</span><br><span class=\"es-t\">Paul: Yo trabajo en una empresa que vende tractores y ella escribe para un periódico.</span><br><span class=\"es-t\">Señor: Yo vivo en Buenos Aires. Trabajo en una agencia de viajes.</span></div>", "Señor, señora – mit oder ohne Artikel?": "Señor, señora – with or without the article?", "<p>Wenn man <b>über</b> jemanden spricht, steht ein Artikel: <span class=\"es-t\">El señor Garrido es cantante.</span></p><p>Wenn man jemanden <b>direkt anspricht</b>, steht <b>kein</b> Artikel: <span class=\"es-t\">Un momento, señora Domínguez.</span></p>": "<p>When you talk <b>about</b> someone, there's an article: <span class=\"es-t\">El señor Garrido es cantante.</span></p><p>When you <b>address</b> someone directly, there's <b>no</b> article: <span class=\"es-t\">Un momento, señora Domínguez.</span></p>", "Direkte Anrede → ohne Artikel.": "Addressing someone directly → no article.", "Bei „¿Es usted …?“ mit Namen steht der Artikel.": "With “¿Es usted …?” plus a name, the article is used.", "„estudiar“, „trabajar“ und „ser“": "“estudiar”, “trabajar” and “ser”", "📎 Übungsblatt: Identificación": "📎 Worksheet: Identificación", "Aus deinem Kurs (Semester 3) · Personalausweis lesen, persönliche Fragen": "From a university Spanish course (semester 3) · reading an ID card, personal questions", "<table><tr><td>Nombre</td><td class=\"es-t\">Juan</td></tr><tr><td>Apellidos</td><td class=\"es-t\">García Fernández</td></tr><tr><td>Nacionalidad</td><td class=\"es-t\">español</td></tr><tr><td>Fecha de nacimiento</td><td>30-11-1971</td></tr><tr><td>Lugar de nacimiento</td><td class=\"es-t\">Málaga</td></tr><tr><td>Nombre del padre y de la madre</td><td class=\"es-t\">José y Adela</td></tr><tr><td>Dirección</td><td class=\"es-t\">calle Cisneros, n.º 80, 1.º, Málaga</td></tr></table>\n <div class=\"ex\">Spanier haben <b>zwei Nachnamen</b>: den ersten des Vaters (García) und den ersten der Mutter (Fernández).</div>": "<table><tr><td>Nombre</td><td class=\"es-t\">Juan</td></tr><tr><td>Apellidos</td><td class=\"es-t\">García Fernández</td></tr><tr><td>Nacionalidad</td><td class=\"es-t\">español</td></tr><tr><td>Fecha de nacimiento</td><td>30-11-1971</td></tr><tr><td>Lugar de nacimiento</td><td class=\"es-t\">Málaga</td></tr><tr><td>Nombre del padre y de la madre</td><td class=\"es-t\">José y Adela</td></tr><tr><td>Dirección</td><td class=\"es-t\">calle Cisneros, n.º 80, 1.º, Málaga</td></tr></table>\n <div class=\"ex\">Spaniards have <b>two surnames</b>: the father's first surname (García) and the mother's first surname (Fernández).</div>", "Der zweite Nachname kommt von der Mutter.": "The second surname comes from the mother.", "Frage und Antwort-Typ": "Question and type of answer", "Wie ist deine E-Mail-Adresse?": "What's your e-mail address?", "Fülle deinen eigenen Ausweis auf Spanisch aus – in ganzen Sätzen: Name, Nationalität, Geburtsdatum und -ort, Namen der Eltern, Adresse.": "Fill in your own ID card in Spanish – in full sentences: name, nationality, date and place of birth, parents' names, address.", "persönliche Angaben, Zahlen, Datum": "personal details, numbers, dates", "Familie · Aussehen & Charakter · nach der Anzahl fragen · über eine Firma sprechen · Gefallen & Interesse": "Family · appearance & character · asking how many · talking about a company · likes & interests", "Familie": "Family", "Adjektive & Angleichung": "Adjectives & agreement", "ser oder estar?": "ser or estar?", "Abendessen mit den Mitbewohnern": "Dinner with the flatmates", "Erster Abend in deiner WG in Sants. Deine Mitbewohnerin Clara kocht und fragt dich über deine Familie und deine Interessen aus.": "First evening in your shared flat in Sants. Your flatmate Clara is cooking and asks you about your family and your interests.", "Erzähl von deiner Familie (wer, wie alt, wie sie sind, wo sie wohnen) und sag, was dir gefällt und was dich stört. Frag Clara auch nach ihrer Familie.": "Talk about your family (who, how old, what they're like, where they live) and say what you like and what bothers you. Ask Clara about her family too.", "Vater / Mutter": "father / mother", "die Eltern": "the parents", "Bruder / Schwester": "brother / sister", "die Geschwister / Brüder": "the siblings / brothers", "Sohn / Tochter": "son / daughter", "Großvater / Großmutter": "grandfather / grandmother", "Enkel / Enkelin": "grandson / granddaughter", "Onkel / Tante": "uncle / aunt", "Cousin / Cousine": "cousin (m / f)", "der/die Partner/in": "the partner", "fester Freund / feste Freundin": "boyfriend / girlfriend", "Männliche Mehrzahl = gemischte Gruppe": "Masculine plural = mixed group", "<table><tr><td class=\"es-t\">el padre + la madre</td><td>=</td><td class=\"es-t\">los padres</td></tr><tr><td class=\"es-t\">el hermano + la hermana</td><td>=</td><td class=\"es-t\">los hermanos</td></tr></table>\n <div class=\"ex\"><span class=\"es-t\">¿Tienes hermanos?</span> fragt also nach Geschwistern allgemein. Antwort z. B.: <span class=\"es-t\">Sí, tengo un hermano.</span> / <span class=\"es-t\">No, soy hijo único.</span> (Einzelkind)</div>": "<table><tr><td class=\"es-t\">el padre + la madre</td><td>=</td><td class=\"es-t\">los padres</td></tr><tr><td class=\"es-t\">el hermano + la hermana</td><td>=</td><td class=\"es-t\">los hermanos</td></tr></table>\n <div class=\"ex\"><span class=\"es-t\">¿Tienes hermanos?</span> therefore asks about siblings in general. Answer e.g.: <span class=\"es-t\">Sí, tengo un hermano.</span> / <span class=\"es-t\">No, soy hijo único.</span> (only child)</div>", "Possessivbegleiter (mein, dein, sein …)": "Possessives (my, your, his …)", "<table><tr><th></th><th>Singular</th><th>Plural</th></tr>\n <tr><td>mein</td><td class=\"es-t\">mi tío / tía</td><td class=\"es-t\">mis tíos / tías</td></tr>\n <tr><td>dein</td><td class=\"es-t\">tu tío / tía</td><td class=\"es-t\">tus tíos / tías</td></tr>\n <tr><td>sein / ihr / Ihr</td><td class=\"es-t\">su tío / tía</td><td class=\"es-t\">sus tíos / tías</td></tr>\n <tr><td>unser</td><td class=\"es-t\">nuestro tío / nuestra tía</td><td class=\"es-t\">nuestros tíos / nuestras tías</td></tr>\n <tr><td>euer</td><td class=\"es-t\">vuestro tío / vuestra tía</td><td class=\"es-t\">vuestros tíos / vuestras tías</td></tr>\n <tr><td>ihr (Pl.) / Ihr</td><td class=\"es-t\">su tío / tía</td><td class=\"es-t\">sus tíos / tías</td></tr></table>\n <div class=\"ojo\">Der Begleiter richtet sich nach dem <b>Besitz</b>, nicht nach dem Besitzer: <span class=\"es-t\">mis padres</span> (Plural, weil Eltern Plural). <b>su/sus</b> kann sein / ihr / Ihr / ihr (Pl.) heißen – der Kontext entscheidet.</div>": "<table><tr><th></th><th>Singular</th><th>Plural</th></tr>\n <tr><td>my</td><td class=\"es-t\">mi tío / tía</td><td class=\"es-t\">mis tíos / tías</td></tr>\n <tr><td>your</td><td class=\"es-t\">tu tío / tía</td><td class=\"es-t\">tus tíos / tías</td></tr>\n <tr><td>his / her / your (formal)</td><td class=\"es-t\">su tío / tía</td><td class=\"es-t\">sus tíos / tías</td></tr>\n <tr><td>our</td><td class=\"es-t\">nuestro tío / nuestra tía</td><td class=\"es-t\">nuestros tíos / nuestras tías</td></tr>\n <tr><td>your (pl.)</td><td class=\"es-t\">vuestro tío / vuestra tía</td><td class=\"es-t\">vuestros tíos / vuestras tías</td></tr>\n <tr><td>their / your (formal pl.)</td><td class=\"es-t\">su tío / tía</td><td class=\"es-t\">sus tíos / tías</td></tr></table>\n <div class=\"ojo\">The possessive agrees with the <b>thing owned</b>, not the owner: <span class=\"es-t\">mis padres</span> (plural, because parents is plural). <b>su/sus</b> can mean his / her / your / their – context decides.</div>", "abuela ist weiblich → <i>nuestra</i>.": "abuela is feminine → <i>nuestra</i>.", "Der Vater meiner Mutter ist mein …": "My mother's father is my …", "Die Tochter meines Onkels ist meine …": "My uncle's daughter is my …", "„Marta y su hermano“ – wessen Bruder?": "“Marta y su hermano” – whose brother?", "<i>su</i> bezieht sich hier auf Marta.": "Here <i>su</i> refers to Marta.", "Ich habe einen Bruder und zwei Cousinen.": "I have a brother and two (female) cousins.", "Hast du Geschwister?": "Do you have any brothers or sisters?", "Adjektive passen sich an": "Adjectives agree", "<table><tr><th></th><th>männlich</th><th>weiblich</th></tr>\n <tr><td>-o / -a</td><td class=\"es-t\">un hombre delgado</td><td class=\"es-t\">una mujer delgada</td></tr>\n <tr><td>-e / Konsonant: gleich</td><td class=\"es-t\">un niño alegre / un producto especial</td><td class=\"es-t\">una niña alegre / una persona especial</td></tr>\n <tr><td>Plural</td><td class=\"es-t\">hombres delgados</td><td class=\"es-t\">mujeres delgadas</td></tr></table>\n <p>Das Adjektiv steht normalerweise <b>nach</b> dem Substantiv.</p>\n <h3>Abstufen</h3><table><tr><td class=\"es-t\">Es muy alto.</td><td>sehr</td></tr><tr><td class=\"es-t\">Es bastante alto.</td><td>ziemlich</td></tr><tr><td class=\"es-t\">Es un poco vago.</td><td>ein bisschen (meist bei Negativem)</td></tr></table>\n <div class=\"ojo\"><span class=\"es-t\">muy, bastante, un poco</span> verändern sich nicht.</div>": "<table><tr><th></th><th>masculine</th><th>feminine</th></tr>\n <tr><td>-o / -a</td><td class=\"es-t\">un hombre delgado</td><td class=\"es-t\">una mujer delgada</td></tr>\n <tr><td>-e / consonant: the same</td><td class=\"es-t\">un niño alegre / un producto especial</td><td class=\"es-t\">una niña alegre / una persona especial</td></tr>\n <tr><td>Plural</td><td class=\"es-t\">hombres delgados</td><td class=\"es-t\">mujeres delgadas</td></tr></table>\n <p>The adjective normally comes <b>after</b> the noun.</p>\n <h3>Degrees</h3><table><tr><td class=\"es-t\">Es muy alto.</td><td>very</td></tr><tr><td class=\"es-t\">Es bastante alto.</td><td>quite</td></tr><tr><td class=\"es-t\">Es un poco vago.</td><td>a bit (usually with negative traits)</td></tr></table>\n <div class=\"ojo\"><span class=\"es-t\">muy, bastante, un poco</span> never change.</div>", "groß": "tall", "klein": "short", "schlank": "slim", "dick": "fat", "hübsch, gutaussehend": "good-looking", "jung": "young", "älter, alt": "older, old", "dunkelhaarig": "dark-haired", "hat lange / kurze Haare": "has long / short hair", "sympathisch, nett": "nice, friendly", "unsympathisch": "unfriendly", "fleißig": "hard-working", "faul": "lazy", "ordentlich": "tidy", "chaotisch": "chaotic", "optimistisch": "optimistic", "pessimistisch": "pessimistic", "fröhlich": "cheerful", "traurig": "sad", "schüchtern": "shy", "offen": "open", "Finde das Gegenteil": "Find the opposite", "Was klingt höflicher, wenn jemand faul ist?": "What sounds more polite when someone is lazy?", "<i>un poco</i> schwächt negative Eigenschaften ab.": "<i>un poco</i> softens negative traits.", "Mein Vater ist groß und ein bisschen chaotisch.": "My father is tall and a bit chaotic.", "Meine Schwestern sind sehr sympathisch.": "My sisters are very nice.", "Meine Mutter ist klein, dunkelhaarig und sehr fröhlich.": "My mother is short, dark-haired and very cheerful.", "estar · ser oder estar?": "estar · ser or estar?", "sein (Ort, Befinden)": "to be (location, how you are)", "<p>Beide heißen „sein“ – aber:</p>\n <table><tr><th>ser – Wer/Was ist es?</th><th>estar – Wo? Wie geht’s?</th></tr>\n <tr><td class=\"es-t\">Es Juan. <span class=\"muted\">(Name)</span></td><td class=\"es-t\">Estoy en Barcelona. <span class=\"muted\">(Ort)</span></td></tr>\n <tr><td class=\"es-t\">Es ingeniera. <span class=\"muted\">(Beruf)</span></td><td class=\"es-t\">La FIB está en Campus Nord. <span class=\"muted\">(Ort)</span></td></tr>\n <tr><td class=\"es-t\">Es de Cádiz. <span class=\"muted\">(Herkunft)</span></td><td class=\"es-t\">¿Cómo estás? – Estoy bien. <span class=\"muted\">(Befinden)</span></td></tr>\n <tr><td class=\"es-t\">Es alto y simpático. <span class=\"muted\">(Eigenschaft)</span></td><td class=\"es-t\">Estoy cansado. <span class=\"muted\">(Zustand gerade)</span></td></tr></table>\n <div class=\"ex\">Merkhilfe: <b>ser</b> = was jemand/etwas <b>ist</b> (Identität). <b>estar</b> = wo/wie jemand <b>sich befindet</b>.</div>": "<p>Both mean “to be” – but:</p>\n <table><tr><th>ser – Who/what is it?</th><th>estar – Where? How are you?</th></tr>\n <tr><td class=\"es-t\">Es Juan. <span class=\"muted\">(name)</span></td><td class=\"es-t\">Estoy en Barcelona. <span class=\"muted\">(place)</span></td></tr>\n <tr><td class=\"es-t\">Es ingeniera. <span class=\"muted\">(job)</span></td><td class=\"es-t\">La FIB está en Campus Nord. <span class=\"muted\">(place)</span></td></tr>\n <tr><td class=\"es-t\">Es de Cádiz. <span class=\"muted\">(origin)</span></td><td class=\"es-t\">¿Cómo estás? – Estoy bien. <span class=\"muted\">(how you are)</span></td></tr>\n <tr><td class=\"es-t\">Es alto y simpático. <span class=\"muted\">(characteristic)</span></td><td class=\"es-t\">Estoy cansado. <span class=\"muted\">(current state)</span></td></tr></table>\n <div class=\"ex\">Memory aid: <b>ser</b> = what someone/something <b>is</b> (identity). <b>estar</b> = where/how someone <b>is right now</b>.</div>", "Ort → <b>estar</b>.": "Place → <b>estar</b>.", "Beruf → <b>ser</b>.": "Job → <b>ser</b>.", "Momentaner Zustand → <b>estar</b>.": "Current state → <b>estar</b>.", "Herkunft → <b>ser</b>.": "Origin → <b>ser</b>.", "Charaktereigenschaft → <b>ser</b>.": "Character trait → <b>ser</b>.", "Meine Eltern sind in Mannheim.": "My parents are in Mannheim.", "Wie geht es euch?": "How are you (all)?", "Me gusta … – „es gefällt mir“": "Me gusta … – “it pleases me”", "<p><b>gustar</b> funktioniert anders als im Deutschen: Wörtlich heißt es „etwas gefällt mir“. Das Verb richtet sich nach der Sache, die gefällt:</p>\n <table><tr><th>Person</th><th>Singular / Infinitiv</th><th>Plural</th></tr>\n <tr><td>(a mí) <b>me</b></td><td rowspan=\"6\" class=\"es-t\">gusta la música<br>gusta viajar</td><td rowspan=\"6\" class=\"es-t\">gustan los idiomas<br>gustan las fiestas</td></tr>\n <tr><td>(a ti) <b>te</b></td></tr><tr><td>(a él / ella / usted) <b>le</b></td></tr><tr><td>(a nosotros/-as) <b>nos</b></td></tr><tr><td>(a vosotros/-as) <b>os</b></td></tr><tr><td>(a ellos / ellas / ustedes) <b>les</b></td></tr></table>\n <p>Genauso: <span class=\"es-t\">interesar</span> (interessieren), <span class=\"es-t\">molestar</span> (stören).</p>\n <div class=\"ojo\">Nach diesen Verben steht der Artikel: <span class=\"es-t\">Me gusta <b>la</b> música</span> (nicht „me gusta música“).</div>\n <table><tr><td class=\"es-t\">¿Te gusta la rutina?</td><td class=\"es-t\">Sí, mucho. / Sí, bastante. / No, nada.</td></tr><tr><td class=\"es-t\">¿Le interesa viajar?</td><td class=\"es-t\">No mucho.</td></tr><tr><td class=\"es-t\">¿Te molestan las discusiones?</td><td class=\"es-t\">Un poco.</td></tr></table>": "<p><b>gustar</b> works differently from English “like”: literally it means “something pleases me”. The verb agrees with the thing that is liked:</p>\n <table><tr><th>Person</th><th>Singular / infinitive</th><th>Plural</th></tr>\n <tr><td>(a mí) <b>me</b></td><td rowspan=\"6\" class=\"es-t\">gusta la música<br>gusta viajar</td><td rowspan=\"6\" class=\"es-t\">gustan los idiomas<br>gustan las fiestas</td></tr>\n <tr><td>(a ti) <b>te</b></td></tr><tr><td>(a él / ella / usted) <b>le</b></td></tr><tr><td>(a nosotros/-as) <b>nos</b></td></tr><tr><td>(a vosotros/-as) <b>os</b></td></tr><tr><td>(a ellos / ellas / ustedes) <b>les</b></td></tr></table>\n <p>The same: <span class=\"es-t\">interesar</span> (to interest), <span class=\"es-t\">molestar</span> (to bother).</p>\n <div class=\"ojo\">After these verbs the article is used: <span class=\"es-t\">Me gusta <b>la</b> música</span> (not “me gusta música”).</div>\n <table><tr><td class=\"es-t\">¿Te gusta la rutina?</td><td class=\"es-t\">Sí, mucho. / Sí, bastante. / No, nada.</td></tr><tr><td class=\"es-t\">¿Le interesa viajar?</td><td class=\"es-t\">No mucho.</td></tr><tr><td class=\"es-t\">¿Te molestan las discusiones?</td><td class=\"es-t\">Un poco.</td></tr></table>", "<i>los idiomas</i> ist Plural → <i>gustan</i>.": "<i>los idiomas</i> is plural → <i>gustan</i>.", "Infinitiv → immer Singular: <i>gusta</i>.": "Infinitive → always singular: <i>gusta</i>.", "Mir gefällt Barcelona sehr.": "I really like Barcelona.", "Mich stört der Lärm.": "The noise bothers me.", "Was magst du?": "What do you like?", "In der WG-Küche. Dein Mitbewohner Óscar fragt dich aus.": "In the kitchen of the shared flat. Your flatmate Óscar asks you questions.", "Hey, Jonas, kochst du gern?": "Hey, Jonas, do you like cooking?", "<i>la comida</i> ist Singular → <i>gusta</i>.": "<i>la comida</i> is singular → <i>gusta</i>.", "Man sagt <i>me gusta cocinar</i> – nicht „yo gusto“.": "You say <i>me gusta cocinar</i> – not “yo gusto”.", "Mir auch! Und interessierst du dich für Fußball?": "Me too! And are you interested in football?", "Du interessierst dich nicht für Fußball.": "You're not interested in football.", "<i>el fútbol</i> ist Singular → <i>no me interesa</i>.": "<i>el fútbol</i> is singular → <i>no me interesa</i>.", "Óscar hat nichts Negatives gesagt – „yo tampoco“ passt nicht.": "Óscar didn't say anything negative – “yo tampoco” doesn't fit.", "Okay. Und was stört dich in einer WG?": "OK. And what bothers you in a shared flat?", "<i>los platos</i> ist Plural → <i>molestan</i>.": "<i>los platos</i> is plural → <i>molestan</i>.", "Haha! Mich auch. Wir sind gute Mitbewohner.": "Haha! Me too. We're good flatmates.", "Über eine Firma sprechen · ¿cuánto?": "Talking about a company · ¿cuánto?", "¿Cuánto? – nach der Anzahl fragen": "¿Cuánto? – asking how many / how much", "<p><b>cuánto</b> richtet sich nach dem Substantiv:</p>\n <table><tr><td class=\"es-t\">¿Cuánto tiempo pasas con tu familia?</td><td>m. Sg.</td></tr>\n <tr><td class=\"es-t\">¿Cuánta gente trabaja aquí?</td><td>w. Sg.</td></tr>\n <tr><td class=\"es-t\">¿Cuántos años tienes?</td><td>m. Pl.</td></tr>\n <tr><td class=\"es-t\">¿Cuántas horas trabajas?</td><td>w. Pl.</td></tr></table>": "<p><b>cuánto</b> agrees with the noun:</p>\n <table><tr><td class=\"es-t\">¿Cuánto tiempo pasas con tu familia?</td><td>m. sg.</td></tr>\n <tr><td class=\"es-t\">¿Cuánta gente trabaja aquí?</td><td>f. sg.</td></tr>\n <tr><td class=\"es-t\">¿Cuántos años tienes?</td><td>m. pl.</td></tr>\n <tr><td class=\"es-t\">¿Cuántas horas trabajas?</td><td>f. pl.</td></tr></table>", "Über eine Firma sprechen": "Talking about a company", "das Familienunternehmen": "the family business", "der/die Gründer/in": "the founder", "die Branche": "the sector / industry", "die Angestellten": "the employees", "exportieren": "to export", "verkaufen": "to sell", "hat … Jahre Geschichte": "has … years of history", "Marktführer": "market leader", "der Hauptsitz": "the headquarters", "<i>la gente</i> ist weiblich Singular.": "<i>la gente</i> is feminine singular.", "Das Unternehmen hat fast hundert Jahre Geschichte.": "The company has almost a hundred years of history.", "Es ist ein Familienunternehmen aus der Modebranche.": "It's a family business in the fashion industry.", "Wie viele Geschwister hast du?": "How many brothers and sisters do you have?", "Beschreibe deine Familie in 5–7 Sätzen: Wer gehört dazu? Wie alt sind sie, wo wohnen sie, wie sind sie (Aussehen/Charakter), was gefällt ihnen?": "Describe your family in 5–7 sentences: who belongs to it? How old are they, where do they live, what are they like (appearance/character), what do they like?", "Familie, Possessivbegleiter, Adjektivangleichung, ser/estar, gustar": "family, possessives, adjective agreement, ser/estar, gustar", "Über eine Firma & eine Familie lesen": "Reading about a company & a family", "Turrones Navarro es una empresa familiar de Xixona, un pueblo cerca de Alicante. Su {fundador|Gründer} es Jesús Navarro y tiene casi cien años de historia. La empresa {fabrica|stellt her} turrón, un dulce típico de Navidad hecho con {almendras|Mandeln} y miel.\n\nHoy la directora es Carmen Navarro, la nieta del fundador. Carmen tiene 45 años, es muy trabajadora y bastante {exigente|anspruchsvoll}. Su hermano Pablo es el responsable de las ventas: es simpático, muy abierto y un poco caótico. «Somos muy diferentes, pero trabajamos muy bien juntos», dice Carmen.\n\nEn la empresa trabajan 120 personas. Exportan a toda Europa y venden muchos productos en Alemania. A Carmen le gusta mucho su trabajo, pero le molesta una cosa: «En diciembre trabajamos {demasiado|zu viel}. ¡No tengo tiempo para mi familia!»": "Turrones Navarro es una empresa familiar de Xixona, un pueblo cerca de Alicante. Su {fundador|founder} es Jesús Navarro y tiene casi cien años de historia. La empresa {fabrica|makes} turrón, un dulce típico de Navidad hecho con {almendras|almonds} y miel.\n\nHoy la directora es Carmen Navarro, la nieta del fundador. Carmen tiene 45 años, es muy trabajadora y bastante {exigente|demanding}. Su hermano Pablo es el responsable de las ventas: es simpático, muy abierto y un poco caótico. «Somos muy diferentes, pero trabajamos muy bien juntos», dice Carmen.\n\nEn la empresa trabajan 120 personas. Exportan a toda Europa y venden muchos productos en Alemania. A Carmen le gusta mucho su trabajo, pero le molesta una cosa: «En diciembre trabajamos {demasiado|too much}. ¡No tengo tiempo para mi familia!»", "Turrones Navarro ist ein Familienunternehmen aus Xixona, einem Dorf bei Alicante. Sein Gründer ist Jesús Navarro und es hat fast hundert Jahre Geschichte. Die Firma stellt Turrón her, eine typische Weihnachtssüßigkeit aus Mandeln und Honig.\n\nHeute ist die Direktorin Carmen Navarro, die Enkelin des Gründers. Carmen ist 45, sehr fleißig und ziemlich anspruchsvoll. Ihr Bruder Pablo ist für den Verkauf verantwortlich: Er ist sympathisch, sehr offen und ein bisschen chaotisch. „Wir sind sehr verschieden, aber wir arbeiten sehr gut zusammen“, sagt Carmen.\n\nIn der Firma arbeiten 120 Personen. Sie exportieren in ganz Europa und verkaufen viele Produkte in Deutschland. Carmen mag ihre Arbeit sehr, aber eine Sache stört sie: „Im Dezember arbeiten wir zu viel. Ich habe keine Zeit für meine Familie!“": "Turrones Navarro is a family business from Xixona, a village near Alicante. Its founder is Jesús Navarro and it has almost a hundred years of history. The company makes turrón, a typical Christmas sweet made with almonds and honey.\n\nToday the director is Carmen Navarro, the founder's granddaughter. Carmen is 45, very hard-working and quite demanding. Her brother Pablo is in charge of sales: he's friendly, very open and a bit chaotic. “We're very different, but we work very well together,” says Carmen.\n\n120 people work at the company. They export all over Europe and sell many products in Germany. Carmen really likes her job, but one thing bothers her: “In December we work too much. I have no time for my family!”", "En la empresa ___ (arbeiten) 120 personas y ___ (sie exportieren) a toda Europa.": "En la empresa ___ (to work) 120 personas y ___ (they export) a toda Europa.", "📎 Übungsblatt: La familia de Marta": "📎 Worksheet: La familia de Marta", "Aus deinem Kurs (Semester 3) · Familienbeziehungen": "From a university Spanish course (semester 3) · family relationships", "Löse das Kreuzworträtsel aus dem Übungsblatt:": "Solve the crossword from the worksheet:", "Familienbeziehungen erklären": "Explaining family relationships", "<p>Neue Wörter: <span class=\"es-t\">el yerno</span> (Schwiegersohn), <span class=\"es-t\">la nuera</span> (Schwiegertochter), <span class=\"es-t\">el suegro / la suegra</span> (Schwiegervater / -mutter), <span class=\"es-t\">el cuñado / la cuñada</span> (Schwager / Schwägerin), <span class=\"es-t\">el nieto</span> (Enkel).</p>": "<p>New words: <span class=\"es-t\">el yerno</span> (son-in-law), <span class=\"es-t\">la nuera</span> (daughter-in-law), <span class=\"es-t\">el suegro / la suegra</span> (father-/mother-in-law), <span class=\"es-t\">el cuñado / la cuñada</span> (brother-/sister-in-law), <span class=\"es-t\">el nieto</span> (grandson).</p>", "<h3>Familie</h3><p class=\"es-t\">el padre · la madre · los padres · el hermano · la hermana · el hijo · la hija · el abuelo · la abuela · el tío · la tía · el primo · la prima</p>\n<h3>Possessivbegleiter</h3><table><tr><td>mi / mis</td><td>tu / tus</td><td>su / sus</td></tr><tr><td>nuestro/-a/-os/-as</td><td>vuestro/-a/-os/-as</td><td>su / sus</td></tr></table>\n<h3>Adjektive</h3><p>-o/-a: alto/alta · -e & Konsonant gleich: alegre, especial · Plural +s/+es · <b>muy</b> (sehr), <b>bastante</b> (ziemlich), <b>un poco</b> (ein bisschen) bleiben gleich.</p>\n<h3>estar</h3><p>estoy · estás · está · estamos · estáis · están</p>\n<h3>ser oder estar?</h3><table><tr><th>ser</th><th>estar</th></tr><tr><td>Name, Beruf, Herkunft, Eigenschaft</td><td>Ort, Befinden, momentaner Zustand</td></tr><tr><td class=\"es-t\">Es cocinero. Es de Cádiz.</td><td class=\"es-t\">Está en Novelda. ¿Cómo estás?</td></tr></table>\n<h3>gustar & Co.</h3><table><tr><td>me · te · le · nos · os · les</td><td class=\"es-t\">gusta + Sg. / Infinitiv · gustan + Pl.</td></tr><tr><td colspan=\"2\" class=\"es-t\">Me gusta la rutina. Te molesta trabajar con estrés. Le interesan las discusiones.</td></tr></table>\n<h3>¿Cuánto?</h3><p class=\"es-t\">¿Cuánto tiempo? · ¿Cuánta gente? · ¿Cuántos años? · ¿Cuántas horas?</p>": "<h3>Family</h3><p class=\"es-t\">el padre · la madre · los padres · el hermano · la hermana · el hijo · la hija · el abuelo · la abuela · el tío · la tía · el primo · la prima</p>\n<h3>Possessives</h3><table><tr><td>mi / mis</td><td>tu / tus</td><td>su / sus</td></tr><tr><td>nuestro/-a/-os/-as</td><td>vuestro/-a/-os/-as</td><td>su / sus</td></tr></table>\n<h3>Adjectives</h3><p>-o/-a: alto/alta · -e & consonant the same: alegre, especial · plural +s/+es · <b>muy</b> (very), <b>bastante</b> (quite), <b>un poco</b> (a bit) never change.</p>\n<h3>estar</h3><p>estoy · estás · está · estamos · estáis · están</p>\n<h3>ser or estar?</h3><table><tr><th>ser</th><th>estar</th></tr><tr><td>name, job, origin, characteristic</td><td>place, how you are, current state</td></tr><tr><td class=\"es-t\">Es cocinero. Es de Cádiz.</td><td class=\"es-t\">Está en Novelda. ¿Cómo estás?</td></tr></table>\n<h3>gustar & co.</h3><table><tr><td>me · te · le · nos · os · les</td><td class=\"es-t\">gusta + sg. / infinitive · gustan + pl.</td></tr><tr><td colspan=\"2\" class=\"es-t\">Me gusta la rutina. Te molesta trabajar con estrés. Le interesan las discusiones.</td></tr></table>\n<h3>¿Cuánto?</h3><p class=\"es-t\">¿Cuánto tiempo? · ¿Cuánta gente? · ¿Cuántos años? · ¿Cuántas horas?</p>", "Essgewohnheiten · Häufigkeit · Uhrzeit · Tisch reservieren · im Restaurant bestellen · einen Vorschlag machen": "Eating habits · frequency · telling the time · booking a table · ordering in a restaurant · making a suggestion", "Lebensmittel & Mahlzeiten": "Food & meals", "Wochentage": "Days of the week", "Häufigkeit (siempre, a veces, nunca …)": "Frequency (siempre, a veces, nunca …)", "Uhrzeit": "Telling the time", "direkte Objektpronomen lo/la/los/las": "direct object pronouns lo/la/los/las", "se + 3. Person": "se + 3rd person", "Mengenangaben": "Quantities", "Nationalitäten": "Nationalities", "Menú del día in der Barceloneta": "Menú del día in Barceloneta", "Mittagspause mit einer Kollegin in einem kleinen Restaurant in der Barceloneta. Es gibt ein Menú del día für 14 €: drei Vorspeisen, drei Hauptgerichte, Dessert, Getränk.": "Lunch break with a colleague in a small restaurant in Barceloneta. There's a menú del día for €14: three starters, three mains, dessert, drink.", "Bestelle ein komplettes Menú del día (primero, segundo, postre, bebida), frag nach, was in einem Gericht drin ist, und bitte um die Rechnung.": "Order a complete menú del día (primero, segundo, postre, bebida), ask what's in a dish and ask for the bill.", "Essen & Häufigkeit": "Food & frequency", "Essenszeiten in Spanien": "Mealtimes in Spain", "<table><tr><th>Mahlzeit</th><th>Verb</th><th>typische Uhrzeit</th></tr>\n <tr><td class=\"es-t\">el desayuno</td><td class=\"es-t\">desayunar</td><td>7:30 – 9:00 (oft nur Kaffee + Toast)</td></tr>\n <tr><td class=\"es-t\">el almuerzo</td><td class=\"es-t\">almorzar</td><td>ca. 11:00 (kleiner Snack, z. B. bocadillo)</td></tr>\n <tr><td class=\"es-t\">la comida</td><td class=\"es-t\">comer</td><td>14:00 – 15:30 – Hauptmahlzeit!</td></tr>\n <tr><td class=\"es-t\">la merienda</td><td class=\"es-t\">merendar</td><td>ca. 18:00</td></tr>\n <tr><td class=\"es-t\">la cena</td><td class=\"es-t\">cenar</td><td>21:00 – 22:30</td></tr></table>\n <div class=\"ojo\"><span class=\"es-t\">comer</span> heißt „essen“ allgemein, aber auch speziell „zu Mittag essen“: <span class=\"es-t\">¿Dónde comes hoy?</span></div>": "<table><tr><th>Meal</th><th>Verb</th><th>typical time</th></tr>\n <tr><td class=\"es-t\">el desayuno</td><td class=\"es-t\">desayunar</td><td>7:30 – 9:00 (often just coffee + toast)</td></tr>\n <tr><td class=\"es-t\">el almuerzo</td><td class=\"es-t\">almorzar</td><td>approx. 11:00 (small snack, e.g. bocadillo)</td></tr>\n <tr><td class=\"es-t\">la comida</td><td class=\"es-t\">comer</td><td>14:00 – 15:30 – main meal!</td></tr>\n <tr><td class=\"es-t\">la merienda</td><td class=\"es-t\">merendar</td><td>approx. 18:00</td></tr>\n <tr><td class=\"es-t\">la cena</td><td class=\"es-t\">cenar</td><td>21:00 – 22:30</td></tr></table>\n <div class=\"ojo\"><span class=\"es-t\">comer</span> means “to eat” in general, but also specifically “to have lunch”: <span class=\"es-t\">¿Dónde comes hoy?</span></div>", "Lebensmittel & Getränke": "Food & drinks", "das Brot": "the bread", "das Obst": "the fruit", "das Gemüse": "the vegetables", "das Fleisch": "the meat", "der Fisch": "the fish", "die Meeresfrüchte": "the seafood", "das Hähnchen": "the chicken", "die Eier": "the eggs", "der Käse": "the cheese", "der Schinken": "the ham", "der Reis": "the rice", "die Milch": "the milk", "das Wasser (mit / ohne Kohlensäure)": "the water (sparkling / still)", "der Saft": "the juice", "der Wein": "the wine", "das Bier": "the beer", "nehmen; essen/trinken": "to have (food/drink)", "Montag": "Monday", "Dienstag": "Tuesday", "Mittwoch": "Wednesday", "Donnerstag": "Thursday", "Freitag": "Friday", "Samstag": "Saturday", "Sonntag": "Sunday", "das Wochenende": "the weekend", "Häufigkeit & Wochentage": "Frequency & days of the week", "<table><tr><td class=\"es-t\">siempre</td><td>immer</td></tr><tr><td class=\"es-t\">todos los días</td><td>jeden Tag</td></tr><tr><td class=\"es-t\">muchas veces</td><td>oft</td></tr><tr><td class=\"es-t\">a veces</td><td>manchmal</td></tr><tr><td class=\"es-t\">pocas veces</td><td>selten</td></tr><tr><td class=\"es-t\">nunca</td><td>nie</td></tr><tr><td class=\"es-t\">dos veces a la semana</td><td>zweimal pro Woche</td></tr><tr><td class=\"es-t\">cinco veces al día</td><td>fünfmal am Tag</td></tr></table>\n <div class=\"ojo\">Steht <b>nunca</b> nach dem Verb, braucht man zusätzlich <b>no</b>: <span class=\"es-t\">Nunca tomo pescado.</span> = <span class=\"es-t\">No tomo nunca pescado.</span></div>\n <p>Wochentage mit Artikel: <span class=\"es-t\">el lunes</span> = am Montag (diesen), <span class=\"es-t\">los lunes</span> = montags (jeden). <span class=\"es-t\">De lunes a viernes</span> = Montag bis Freitag.</p>": "<table><tr><td class=\"es-t\">siempre</td><td>always</td></tr><tr><td class=\"es-t\">todos los días</td><td>every day</td></tr><tr><td class=\"es-t\">muchas veces</td><td>often</td></tr><tr><td class=\"es-t\">a veces</td><td>sometimes</td></tr><tr><td class=\"es-t\">pocas veces</td><td>rarely</td></tr><tr><td class=\"es-t\">nunca</td><td>never</td></tr><tr><td class=\"es-t\">dos veces a la semana</td><td>twice a week</td></tr><tr><td class=\"es-t\">cinco veces al día</td><td>five times a day</td></tr></table>\n <div class=\"ojo\">If <b>nunca</b> comes after the verb, you also need <b>no</b>: <span class=\"es-t\">Nunca tomo pescado.</span> = <span class=\"es-t\">No tomo nunca pescado.</span></div>\n <p>Days of the week with the article: <span class=\"es-t\">el lunes</span> = on Monday (this one), <span class=\"es-t\">los lunes</span> = on Mondays (every). <span class=\"es-t\">De lunes a viernes</span> = Monday to Friday.</p>", "Wie oft?": "How often?", "jeden Tag": "every day", "„Montags habe ich Spanischkurs.“": "“On Mondays I have Spanish class.”", "Regelmäßig → <i>los lunes</i> (Plural).": "Regularly → <i>los lunes</i> (plural).", "Ich esse nie Fleisch.": "I never eat meat.", "Ich trinke manchmal Wein.": "I sometimes drink wine.", "Ich frühstücke jeden Tag um acht.": "I have breakfast every day at eight.", "Stammwechsel o→ue und e→ie": "Stem change o→ue and e→ie", "Verben mit Stammwechsel": "Stem-changing verbs", "<p>Bei manchen Verben ändert sich der betonte Stammvokal – aber <b>nicht</b> bei nosotros und vosotros:</p>\n <table><tr><th></th><th>poder (o→ue)<br><span class=\"muted\">können</span></th><th>querer (e→ie)<br><span class=\"muted\">wollen, mögen</span></th><th>preferir (e→ie)<br><span class=\"muted\">vorziehen</span></th></tr>\n <tr><td>yo</td><td class=\"es-t\">puedo</td><td class=\"es-t\">quiero</td><td class=\"es-t\">prefiero</td></tr>\n <tr><td>tú</td><td class=\"es-t\">puedes</td><td class=\"es-t\">quieres</td><td class=\"es-t\">prefieres</td></tr>\n <tr><td>él / ella / usted</td><td class=\"es-t\">puede</td><td class=\"es-t\">quiere</td><td class=\"es-t\">prefiere</td></tr>\n <tr><td>nosotros/-as</td><td class=\"es-t\">podemos</td><td class=\"es-t\">queremos</td><td class=\"es-t\">preferimos</td></tr>\n <tr><td>vosotros/-as</td><td class=\"es-t\">podéis</td><td class=\"es-t\">queréis</td><td class=\"es-t\">preferís</td></tr>\n <tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">pueden</td><td class=\"es-t\">quieren</td><td class=\"es-t\">prefieren</td></tr></table>\n <div class=\"ex\">Merkbild „Stiefel“: Die Formen yo, tú, él, ellos (Stiefelform in der Tabelle) wechseln – nosotros/vosotros nicht.</div>\n <p>Genauso: <span class=\"es-t\">almorzar (almuerzo), costar (cuesta), volver (vuelvo), empezar (empiezo), pensar (pienso)</span>.</p>": "<p>In some verbs the stressed stem vowel changes – but <b>not</b> for nosotros and vosotros:</p>\n <table><tr><th></th><th>poder (o→ue)<br><span class=\"muted\">can</span></th><th>querer (e→ie)<br><span class=\"muted\">to want, to love</span></th><th>preferir (e→ie)<br><span class=\"muted\">to prefer</span></th></tr>\n <tr><td>yo</td><td class=\"es-t\">puedo</td><td class=\"es-t\">quiero</td><td class=\"es-t\">prefiero</td></tr>\n <tr><td>tú</td><td class=\"es-t\">puedes</td><td class=\"es-t\">quieres</td><td class=\"es-t\">prefieres</td></tr>\n <tr><td>él / ella / usted</td><td class=\"es-t\">puede</td><td class=\"es-t\">quiere</td><td class=\"es-t\">prefiere</td></tr>\n <tr><td>nosotros/-as</td><td class=\"es-t\">podemos</td><td class=\"es-t\">queremos</td><td class=\"es-t\">preferimos</td></tr>\n <tr><td>vosotros/-as</td><td class=\"es-t\">podéis</td><td class=\"es-t\">queréis</td><td class=\"es-t\">preferís</td></tr>\n <tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">pueden</td><td class=\"es-t\">quieren</td><td class=\"es-t\">prefieren</td></tr></table>\n <div class=\"ex\">Memory aid “boot”: the forms yo, tú, él, ellos (boot shape in the table) change – nosotros/vosotros don't.</div>\n <p>The same: <span class=\"es-t\">almorzar (almuerzo), costar (cuesta), volver (vuelvo), empezar (empiezo), pensar (pienso)</span>.</p>", "können": "can, to be able to", "wollen": "to want", "vosotros → kein Stammwechsel: <i>queréis</i>.": "vosotros → no stem change: <i>queréis</i>.", "Willst du Wasser oder Wein?": "Do you want water or wine?", "Ich bin allergisch gegen Milch.": "I'm allergic to milk.", "<table><tr><td>13:00</td><td class=\"es-t\">Es la una.</td></tr><tr><td>14:00</td><td class=\"es-t\">Son las dos.</td></tr><tr><td>14:15</td><td class=\"es-t\">Son las dos y cuarto.</td></tr><tr><td>14:30</td><td class=\"es-t\">Son las dos y media.</td></tr><tr><td>14:45</td><td class=\"es-t\">Son las tres menos cuarto.</td></tr><tr><td>14:50</td><td class=\"es-t\">Son las tres menos diez.</td></tr><tr><td>14:10</td><td class=\"es-t\">Son las dos y diez.</td></tr></table>\n <div class=\"ojo\">Nur bei 1 Uhr: <b>es la</b> una. Sonst: <b>son las</b> …</div>\n <h3>Wann? – a las …</h3><table><tr><td class=\"es-t\">¿A qué hora comes?</td><td class=\"es-t\">A las dos y media.</td></tr><tr><td class=\"es-t\">El martes por la tarde tengo una reunión.</td><td>am Dienstagnachmittag</td></tr><tr><td class=\"es-t\">a las nueve de la mañana / de la noche</td><td>um 9 Uhr morgens / abends</td></tr><tr><td class=\"es-t\">de dos a diez</td><td>von zwei bis zehn</td></tr></table>\n <p><span class=\"es-t\">por la mañana / por la tarde / por la noche</span> – ohne Uhrzeit. Mit Uhrzeit: <span class=\"es-t\">de la mañana</span>.</p>": "<table><tr><td>13:00</td><td class=\"es-t\">Es la una.</td></tr><tr><td>14:00</td><td class=\"es-t\">Son las dos.</td></tr><tr><td>14:15</td><td class=\"es-t\">Son las dos y cuarto.</td></tr><tr><td>14:30</td><td class=\"es-t\">Son las dos y media.</td></tr><tr><td>14:45</td><td class=\"es-t\">Son las tres menos cuarto.</td></tr><tr><td>14:50</td><td class=\"es-t\">Son las tres menos diez.</td></tr><tr><td>14:10</td><td class=\"es-t\">Son las dos y diez.</td></tr></table>\n <div class=\"ojo\">Only for 1 o'clock: <b>es la</b> una. Otherwise: <b>son las</b> …</div>\n <h3>When? – a las …</h3><table><tr><td class=\"es-t\">¿A qué hora comes?</td><td class=\"es-t\">A las dos y media.</td></tr><tr><td class=\"es-t\">El martes por la tarde tengo una reunión.</td><td>on Tuesday afternoon</td></tr><tr><td class=\"es-t\">a las nueve de la mañana / de la noche</td><td>at 9 in the morning / evening</td></tr><tr><td class=\"es-t\">de dos a diez</td><td>from two to ten</td></tr></table>\n <p><span class=\"es-t\">por la mañana / por la tarde / por la noche</span> – without a time. With a time: <span class=\"es-t\">de la mañana</span>.</p>", "Es ist 15:30.": "It's 15:30.", "Es ist 13:15.": "It's 13:15.", "Es ist 19:45.": "It's 19:45.", "Schreib die Uhrzeit aus: 10:20": "Write out the time: 10:20", "Hör zu und schreib den Satz.": "Listen and write the sentence.", "Die Besprechung ist um halb zwölf.": "The meeting is at half past eleven.", "Am Montagmorgen habe ich eine Besprechung.": "On Monday morning I have a meeting.", "einen Tisch reservieren": "to book a table", "Für wie viele Personen?": "For how many people?", "Auf welchen Namen?": "In whose name?", "es ist voll": "it's full", "das Tagesmenü": "the set lunch menu", "als Vorspeise / als Hauptgericht": "as a starter / as a main course", "der Nachtisch": "the dessert", "Und zu trinken?": "And to drink?", "die Rechnung, bitte": "the bill, please", "mit Karte zahlen": "to pay by card", "Kellner/in": "waiter / waitress", "Was ist in … drin?": "What's in …?", "<p>Ein schon genanntes Objekt (Akkusativ) ersetzt man durch <b>lo, la, los, las</b>:</p>\n <table><tr><th></th><th>männlich</th><th>weiblich</th></tr><tr><td>Sg.</td><td class=\"es-t\">lo</td><td class=\"es-t\">la</td></tr><tr><td>Pl.</td><td class=\"es-t\">los</td><td class=\"es-t\">las</td></tr></table>\n <div class=\"ex\"><span class=\"es-t\">¿Quién compra la carne? – La compro yo.</span><br><span class=\"es-t\">¿Tomas el café con leche? – No, lo tomo solo.</span></div>\n <div class=\"ojo\">Das Pronomen steht <b>vor</b> dem konjugierten Verb, <b>no</b> steht davor: <span class=\"es-t\">No las compro.</span></div>\n <h3>se + 3. Person = „man“</h3><table><tr><td class=\"es-t\">Se puede pagar con tarjeta.</td><td>Man kann mit Karte zahlen.</td></tr><tr><td class=\"es-t\">El gazpacho se come frío.</td><td>Gazpacho isst man kalt.</td></tr><tr><td class=\"es-t\">Aquí se beben vinos italianos.</td><td>Plural-Substantiv → Verb im Plural</td></tr></table>": "<p>An object already mentioned (direct object) is replaced by <b>lo, la, los, las</b>:</p>\n <table><tr><th></th><th>masculine</th><th>feminine</th></tr><tr><td>sg.</td><td class=\"es-t\">lo</td><td class=\"es-t\">la</td></tr><tr><td>pl.</td><td class=\"es-t\">los</td><td class=\"es-t\">las</td></tr></table>\n <div class=\"ex\"><span class=\"es-t\">¿Quién compra la carne? – La compro yo.</span><br><span class=\"es-t\">¿Tomas el café con leche? – No, lo tomo solo.</span></div>\n <div class=\"ojo\">The pronoun goes <b>before</b> the conjugated verb, <b>no</b> goes before it: <span class=\"es-t\">No las compro.</span></div>\n <h3>se + 3rd person = “one / you”</h3><table><tr><td class=\"es-t\">Se puede pagar con tarjeta.</td><td>You can pay by card.</td></tr><tr><td class=\"es-t\">El gazpacho se come frío.</td><td>Gazpacho is eaten cold.</td></tr><tr><td class=\"es-t\">Aquí se beben vinos italianos.</td><td>plural noun → plural verb</td></tr></table>", "„Man kann hier mit Karte zahlen.“": "“You can pay by card here.”", "Du rufst im Restaurant „Can Solé“ an, um für Freitag einen Tisch für ein Teamessen zu reservieren.": "You call the restaurant “Can Solé” to book a table for a team dinner on Friday.", "Can Solé, guten Tag. Ja, bitte?": "Can Solé, good afternoon. Yes, please?", "„Gibt es …?“ = <b>hay</b>.": "“Is there / are there …?” = <b>hay</b>.", "Ja. Für wie viele Personen?": "Yes. For how many people?", "Uhrzeit: <b>a</b> las …": "Time: <b>a</b> las …", "Perfekt. Auf welchen Namen?": "Perfect. In whose name?", "Die Wendung lautet <i>a nombre de</i>.": "The phrase is <i>a nombre de</i>.", "Sehr gut. Bis Freitag.": "Very good. See you on Friday.", "Du bist mit einer Kollegin beim Mittagessen. Der Kellner kommt.": "You're having lunch with a colleague. The waiter comes.", "Hallo. Was möchten Sie als Vorspeise?": "Hello. What would you like as a starter?", "„Für mich“ = <b>para mí</b>.": "“For me” = <b>para mí</b>.", "Und als Hauptgericht?": "And as a main course?", "<i>el pollo</i> ist Singular → <i>lleva</i>.": "<i>el pollo</i> is singular → <i>lleva</i>.", "Knoblauch, Olivenöl und ein bisschen Weißwein.": "Garlic, olive oil and a little white wine.", "<i>el pollo</i> ist männlich → <b>lo</b>.": "<i>el pollo</i> is masculine → <b>lo</b>.", "😄 <i>gasolina</i> = Benzin. Stilles Wasser: <i>agua sin gas</i>.": "😄 <i>gasolina</i> = petrol. Still water: <i>agua sin gas</i>.", "Sehr gut. Kommt sofort.": "Very good. Coming right up.", "<table><tr><td>1 kg</td><td class=\"es-t\">un kilo de patatas</td></tr><tr><td>100 g</td><td class=\"es-t\">cien gramos de jamón</td></tr><tr><td>½ l</td><td class=\"es-t\">medio litro de zumo</td></tr><tr><td>1½ kg</td><td class=\"es-t\">un kilo y medio de carne</td></tr><tr><td></td><td class=\"es-t\">una botella de agua · una lata de cerveza · un paquete de café</td></tr></table>\n <div class=\"ojo\">Zwischen Menge und Produkt steht immer <b>de</b>.</div>": "<table><tr><td>1 kg</td><td class=\"es-t\">un kilo de patatas</td></tr><tr><td>100 g</td><td class=\"es-t\">cien gramos de jamón</td></tr><tr><td>½ l</td><td class=\"es-t\">medio litro de zumo</td></tr><tr><td>1½ kg</td><td class=\"es-t\">un kilo y medio de carne</td></tr><tr><td></td><td class=\"es-t\">una botella de agua · una lata de cerveza · un paquete de café</td></tr></table>\n <div class=\"ojo\">Between the quantity and the product there's always <b>de</b>.</div>", "ein halber Liter Milch": "half a litre of milk", "Die Rechnung, bitte.": "The bill, please.", "Text verstehen · Nationalitäten · eigene Gewohnheiten": "Understanding a text · nationalities · your own habits", "En España, muchas personas que {trabajan|arbeiten} en la oficina comen fuera de casa. Una opción muy {popular|beliebt} es el «menú del día». Por un {precio fijo|Festpreis} – normalmente entre 12 y 16 euros – tienes un primer plato, un segundo plato, el postre o un café, pan y una {bebida|Getränk}.\n\nLos primeros platos son muchas veces {ensaladas|Salate}, sopas o verduras. De segundo hay carne o pescado. En Barcelona, por ejemplo, es típico el {arroz|Reis} negro o la {butifarra|katalanische Bratwurst} con judías.\n\nLa comida es la {comida principal|Hauptmahlzeit} del día y la gente no come {deprisa|schnell}: una comida de trabajo puede {durar|dauern} dos horas. Por eso, la cena es más {ligera|leicht} y muy tarde, a las nueve o a las diez de la noche.": "En España, muchas personas que {trabajan|work} en la oficina comen fuera de casa. Una opción muy {popular|popular} es el «menú del día». Por un {precio fijo|fixed price} – normalmente entre 12 y 16 euros – tienes un primer plato, un segundo plato, el postre o un café, pan y una {bebida|drink}.\n\nLos primeros platos son muchas veces {ensaladas|salads}, sopas o verduras. De segundo hay carne o pescado. En Barcelona, por ejemplo, es típico el {arroz|rice} negro o la {butifarra|Catalan sausage} con judías.\n\nLa comida es la {comida principal|main meal} del día y la gente no come {deprisa|fast}: una comida de trabajo puede {durar|last} dos horas. Por eso, la cena es más {ligera|light} y muy tarde, a las nueve o a las diez de la noche.", "In Spanien essen viele Menschen, die im Büro arbeiten, außer Haus. Eine sehr beliebte Option ist das „Tagesmenü“. Zu einem Festpreis – normalerweise zwischen 12 und 16 Euro – bekommst du eine Vorspeise, ein Hauptgericht, Nachtisch oder Kaffee, Brot und ein Getränk.\n\nDie Vorspeisen sind oft Salate, Suppen oder Gemüse. Als Hauptgericht gibt es Fleisch oder Fisch. In Barcelona ist z. B. schwarzer Reis oder Butifarra mit Bohnen typisch.\n\nDas Mittagessen ist die Hauptmahlzeit des Tages und man isst nicht schnell: Ein Geschäftsessen kann zwei Stunden dauern. Deshalb ist das Abendessen leichter und sehr spät, um neun oder zehn Uhr abends.": "In Spain many people who work in offices eat out. A very popular option is the “menú del día”. For a fixed price – usually between 12 and 16 euros – you get a starter, a main course, dessert or coffee, bread and a drink.\n\nThe starters are often salads, soups or vegetables. As a main course there's meat or fish. In Barcelona, for example, black rice or butifarra (sausage) with beans is typical.\n\nLunch is the main meal of the day and people don't eat fast: a business lunch can last two hours. That's why dinner is lighter and very late, at nine or ten in the evening.", "<table><tr><th>-o / -a</th><th>Konsonant + -a</th><th>eine Form</th></tr>\n <tr><td class=\"es-t\">suizo / suiza</td><td class=\"es-t\">español / española</td><td class=\"es-t\">belga</td></tr>\n <tr><td class=\"es-t\">argentino / argentina</td><td class=\"es-t\">alemán / alemana</td><td class=\"es-t\">marroquí</td></tr>\n <tr><td class=\"es-t\">italiano / italiana</td><td class=\"es-t\">inglés / inglesa</td><td class=\"es-t\">estadounidense</td></tr>\n <tr><td class=\"es-t\">austriaco / austriaca</td><td class=\"es-t\">francés / francesa</td><td class=\"es-t\">canadiense</td></tr></table>\n <div class=\"ojo\">Nationalitäten werden klein geschrieben. Der Akzent fällt bei der weiblichen Form weg: <span class=\"es-t\">alemán → alemana</span>.</div>": "<table><tr><th>-o / -a</th><th>consonant + -a</th><th>one form</th></tr>\n <tr><td class=\"es-t\">suizo / suiza</td><td class=\"es-t\">español / española</td><td class=\"es-t\">belga</td></tr>\n <tr><td class=\"es-t\">argentino / argentina</td><td class=\"es-t\">alemán / alemana</td><td class=\"es-t\">marroquí</td></tr>\n <tr><td class=\"es-t\">italiano / italiana</td><td class=\"es-t\">inglés / inglesa</td><td class=\"es-t\">estadounidense</td></tr>\n <tr><td class=\"es-t\">austriaco / austriaca</td><td class=\"es-t\">francés / francesa</td><td class=\"es-t\">canadiense</td></tr></table>\n <div class=\"ojo\">Nationalities are written with a small letter. The accent disappears in the feminine form: <span class=\"es-t\">alemán → alemana</span>.</div>", "Laia es ___ (spanisch) y su novio es ___ (französisch).": "Laia es ___ (Spanish) y su novio es ___ (French).", "Beschreibe deine Essgewohnheiten in 5–6 Sätzen: Wann und was isst du? Was isst du nie / oft? Was kannst du nicht essen? Was isst man in Deutschland anders als in Spanien?": "Describe your eating habits in 5–6 sentences: when and what do you eat? What do you never / often eat? What can't you eat? What do people eat differently in your country compared to Spain?", "Desayuno a las … · Normalmente como … · Nunca tomo … · Prefiero … · En Alemania se cena …": "Desayuno a las … · Normalmente como … · Nunca tomo … · Prefiero … · En mi país se cena …", "Häufigkeit, poder/querer/preferir, Uhrzeit, se + 3. Person": "frequency, poder/querer/preferir, time, se + 3rd person", "📎 Übungsblatt: La hora": "📎 Worksheet: La hora", "Aus deinem Kurs (Semester 4) · Uhren lesen": "From a university Spanish course (semester 4) · reading clocks", "Wie spät ist es?": "What time is it?", "📎 Übungsblatt: ¿Algo más? · ¿Qué comen los españoles?": "📎 Worksheet: ¿Algo más? · ¿Qué comen los españoles?", "Aus deinem Kurs (Semester 4) · Verpackungen, Mengen, Essgewohnheiten, aunque": "From a university Spanish course (semester 4) · packaging, quantities, eating habits, aunque", "die Flasche": "the bottle", "die Dose": "the can", "die Packung": "the packet", "die Tüte": "the bag", "das Baguette / Stangenbrot": "the baguette", "die Wochenangebote": "the weekly offers", "Sonst noch etwas?": "Anything else?", "eine Flasche Olivenöl und zwei Packungen Kaffee": "a bottle of olive oil and two packets of coffee", "Zusammenfassung des Artikels aus deinem Übungsblatt.": "Summary of the article from the worksheet.", "Según un estudio, la mayoría de los trabajadores españoles come el menú del día en un restaurante o en la {cantina|Kantine} de la empresa, porque no tienen tiempo para volver a casa. Cuanto más grande es la ciudad, más gente come fuera.\n\nLos jóvenes entre 18 y 35 años prefieren llevarse la {tartera|Brotdose} al trabajo. Entre 35 y 50 años eligen el restaurante o la cantina.\n\nLo que comen depende del clima: en el norte prefieren las comidas de {cuchara|Löffelgerichte (Eintöpfe)}, en zonas más templadas como Valencia, las verduras. Para beber, cuatro de cada diez prefieren el agua; de las bebidas alcohólicas, la más pedida es la cerveza.": "Según un estudio, la mayoría de los trabajadores españoles come el menú del día en un restaurante o en la {cantina|canteen} de la empresa, porque no tienen tiempo para volver a casa. Cuanto más grande es la ciudad, más gente come fuera.\n\nLos jóvenes entre 18 y 35 años prefieren llevarse la {tartera|lunchbox} al trabajo. Entre 35 y 50 años eligen el restaurante o la cantina.\n\nLo que comen depende del clima: en el norte prefieren las comidas de {cuchara|spoon dishes (stews)}, en zonas más templadas como Valencia, las verduras. Para beber, cuatro de cada diez prefieren el agua; de las bebidas alcohólicas, la más pedida es la cerveza.", "Sätze verbinden mit aunque": "Linking sentences with aunque", "<p><b>aunque</b> = obwohl. Damit drückt man einen Gegensatz aus:</p><div class=\"ex\"><span class=\"es-t\">Normalmente como en la cantina, aunque prefiero comer en casa.</span></div>": "<p><b>aunque</b> = although. It expresses a contrast:</p><div class=\"ex\"><span class=\"es-t\">Normalmente como en la cantina, aunque prefiero comer en casa.</span></div>", "Ich esse Fleisch, obwohl ich lieber Fisch esse.": "I eat meat, although I prefer to eat fish.", "<h3>Essgewohnheiten</h3><p class=\"es-t\">Desayuno todos los días. · Como de todo. · Soy vegetariano/-a. · No puedo beber alcohol. · Prefiero el café sin leche.</p>\n<h3>Häufigkeit</h3><p class=\"es-t\">siempre · todos los días · muchas veces · a veces · pocas veces · nunca · dos veces a la semana</p>\n<h3>Wochentage</h3><p class=\"es-t\">lunes · martes · miércoles · jueves · viernes · sábado · domingo — el lunes (diesen) / los lunes (jeden)</p>\n<h3>poder · querer · preferir</h3><table><tr><td>puedo, puedes, puede, podemos, podéis, pueden</td></tr><tr><td>quiero, quieres, quiere, queremos, queréis, quieren</td></tr><tr><td>prefiero, prefieres, prefiere, preferimos, preferís, prefieren</td></tr></table>\n<h3>Uhrzeit</h3><table><tr><td class=\"es-t\">Es la una. · Son las dos y cuarto / y media / menos cuarto.</td></tr><tr><td class=\"es-t\">¿A qué hora …? – A las tres. · por la mañana / tarde / noche</td></tr></table>\n<h3>Restaurant</h3><table><tr><td class=\"es-t\">¿Hay mesas libres? · ¿Para cuántas personas? · ¿A nombre de quién?</td></tr><tr><td class=\"es-t\">De primero … · De segundo … · ¿Y para beber? · La cuenta, por favor.</td></tr></table>\n<h3>Objektpronomen & se</h3><p><b>lo, la, los, las</b> vor dem Verb: <span class=\"es-t\">La compro yo. No lo tomo.</span> · <span class=\"es-t\">Se puede pagar con tarjeta.</span></p>\n<h3>Mengen</h3><p class=\"es-t\">un kilo de · cien gramos de · medio litro de · una botella de</p>": "<h3>Eating habits</h3><p class=\"es-t\">Desayuno todos los días. · Como de todo. · Soy vegetariano/-a. · No puedo beber alcohol. · Prefiero el café sin leche.</p>\n<h3>Frequency</h3><p class=\"es-t\">siempre · todos los días · muchas veces · a veces · pocas veces · nunca · dos veces a la semana</p>\n<h3>Days of the week</h3><p class=\"es-t\">lunes · martes · miércoles · jueves · viernes · sábado · domingo — el lunes (this one) / los lunes (every)</p>\n<h3>poder · querer · preferir</h3><table><tr><td>puedo, puedes, puede, podemos, podéis, pueden</td></tr><tr><td>quiero, quieres, quiere, queremos, queréis, quieren</td></tr><tr><td>prefiero, prefieres, prefiere, preferimos, preferís, prefieren</td></tr></table>\n<h3>Telling the time</h3><table><tr><td class=\"es-t\">Es la una. · Son las dos y cuarto / y media / menos cuarto.</td></tr><tr><td class=\"es-t\">¿A qué hora …? – A las tres. · por la mañana / tarde / noche</td></tr></table>\n<h3>Restaurant</h3><table><tr><td class=\"es-t\">¿Hay mesas libres? · ¿Para cuántas personas? · ¿A nombre de quién?</td></tr><tr><td class=\"es-t\">De primero … · De segundo … · ¿Y para beber? · La cuenta, por favor.</td></tr></table>\n<h3>Object pronouns & se</h3><p><b>lo, la, los, las</b> before the verb: <span class=\"es-t\">La compro yo. No lo tomo.</span> · <span class=\"es-t\">Se puede pagar con tarjeta.</span></p>\n<h3>Quantities</h3><p class=\"es-t\">un kilo de · cien gramos de · medio litro de · una botella de</p>", "Eine Stadt beschreiben · Verkehrsmittel · den Weg beschreiben · Reihenfolge · Ortsangaben": "Describing a city · means of transport · giving directions · sequence · describing location", "Verkehrsmittel (en metro, a pie)": "Transport (en metro, a pie)", "tener que + Infinitiv": "tener que + infinitive", "Weg beschreiben": "Giving directions", "Ortsangaben (cerca de, al lado de …)": "Location (cerca de, al lado de …)", "Verlaufen in der Ciutat Vella": "Lost in the Ciutat Vella", "Du kommst am Liceu aus der Metro (L3) und willst zum Mercado de Santa Caterina, wo du einen Freund triffst. Du fragst eine ältere Dame nach dem Weg.": "You come out of the metro (L3) at Liceu and want to get to the Mercado de Santa Caterina, where you're meeting a friend. You ask an older lady for directions.", "Frag höflich nach dem Weg, frag, ob es weit ist und ob man zu Fuß gehen kann, wiederhole die Beschreibung und bedanke dich.": "Politely ask for directions, ask whether it's far and whether you can walk, repeat the directions and say thank you.", "In der Stadt": "In the city", "das Viertel": "the neighbourhood", "das Zentrum": "the centre", "der Park": "the park", "der Platz": "the square", "das Museum": "the museum", "die Kathedrale": "the cathedral", "das Gebäude": "the building", "der Markt": "the market", "der Strand": "the beach", "der Verkehr": "the traffic", "die Altstadt": "the old town", "die Atmosphäre": "the atmosphere", "hay oder estar?": "hay or estar?", "<table><tr><th>hay = es gibt</th><th>estar = sich befinden</th></tr>\n <tr><td class=\"es-t\">En Barcelona hay una catedral famosa.</td><td class=\"es-t\">La Sagrada Família está en el Eixample.</td></tr>\n <tr><td class=\"es-t\">Hay muchos bares y restaurantes.</td><td class=\"es-t\">Mi hotel está en el casco antiguo.</td></tr>\n <tr><td class=\"es-t\">Hay más de 300 ferias al año.</td><td class=\"es-t\">Los servicios están al lado del restaurante.</td></tr></table>\n <div class=\"ex\"><b>hay</b> + unbestimmter Artikel / Zahl / Menge / ohne Artikel (etwas Unbekanntes).<br><b>está/están</b> + bestimmter Artikel / Name (etwas Bestimmtes – wo ist es?).</div>\n <div class=\"ojo\"><b>hay</b> hat nur eine Form – auch im Plural: <span class=\"es-t\">hay dos parques</span>.</div>": "<table><tr><th>hay = there is / there are</th><th>estar = to be located</th></tr>\n <tr><td class=\"es-t\">En Barcelona hay una catedral famosa.</td><td class=\"es-t\">La Sagrada Família está en el Eixample.</td></tr>\n <tr><td class=\"es-t\">Hay muchos bares y restaurantes.</td><td class=\"es-t\">Mi hotel está en el casco antiguo.</td></tr>\n <tr><td class=\"es-t\">Hay más de 300 ferias al año.</td><td class=\"es-t\">Los servicios están al lado del restaurante.</td></tr></table>\n <div class=\"ex\"><b>hay</b> + indefinite article / number / quantity / no article (something unknown).<br><b>está/están</b> + definite article / name (something specific – where is it?).</div>\n <div class=\"ojo\"><b>hay</b> has only one form – also in the plural: <span class=\"es-t\">hay dos parques</span>.</div>", "muy oder mucho?": "muy or mucho?", "<table><tr><th>mucho/-a/-os/-as + Substantiv (veränderlich)</th><th>muy + Adjektiv/Adverb</th></tr>\n <tr><td class=\"es-t\">mucho tráfico · mucha gente · muchos trenes · muchas obras</td><td class=\"es-t\">Es muy difícil llegar. · Está muy cerca.</td></tr></table>\n <p>Nach dem Verb: <span class=\"es-t\">mucho</span> (unveränderlich): <span class=\"es-t\">No uso mucho la bicicleta. ¿Te gusta? – Sí, mucho.</span></p>": "<table><tr><th>mucho/-a/-os/-as + noun (changes)</th><th>muy + adjective/adverb</th></tr>\n <tr><td class=\"es-t\">mucho tráfico · mucha gente · muchos trenes · muchas obras</td><td class=\"es-t\">Es muy difícil llegar. · Está muy cerca.</td></tr></table>\n <p>After the verb: <span class=\"es-t\">mucho</span> (doesn't change): <span class=\"es-t\">No uso mucho la bicicleta. ¿Te gusta? – Sí, mucho.</span></p>", "El metro es ___ (sehr) rápido y trabajo ___ (viel).": "El metro es ___ (very) rápido y trabajo ___ (a lot).", "In meinem Viertel gibt es viele Parks.": "There are lots of parks in my neighbourhood.", "Die Universität ist sehr weit weg.": "The university is very far away.", "<table><tr><td>yo</td><td class=\"es-t\">voy</td></tr><tr><td>tú</td><td class=\"es-t\">vas</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">va</td></tr><tr><td>nosotros/-as</td><td class=\"es-t\">vamos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">vais</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">van</td></tr></table>\n <table><tr><td><b>a</b> = Richtung (wohin?)</td><td class=\"es-t\">Voy a Guadalajara. · Vamos a la oficina.</td></tr><tr><td><b>en</b> = Verkehrsmittel</td><td class=\"es-t\">Voy en metro / en tren / en coche / en bici / en avión</td></tr><tr><td>zu Fuß</td><td class=\"es-t\">Voy a pie / andando.</td></tr></table>\n <div class=\"ojo\"><b>a + el = al</b>: <span class=\"es-t\">Voy al aeropuerto.</span> (aber: <span class=\"es-t\">a la estación</span>)</div>": "<table><tr><td>yo</td><td class=\"es-t\">voy</td></tr><tr><td>tú</td><td class=\"es-t\">vas</td></tr><tr><td>él / ella / usted</td><td class=\"es-t\">va</td></tr><tr><td>nosotros/-as</td><td class=\"es-t\">vamos</td></tr><tr><td>vosotros/-as</td><td class=\"es-t\">vais</td></tr><tr><td>ellos / ellas / ustedes</td><td class=\"es-t\">van</td></tr></table>\n <table><tr><td><b>a</b> = direction (where to?)</td><td class=\"es-t\">Voy a Guadalajara. · Vamos a la oficina.</td></tr><tr><td><b>en</b> = means of transport</td><td class=\"es-t\">Voy en metro / en tren / en coche / en bici / en avión</td></tr><tr><td>on foot</td><td class=\"es-t\">Voy a pie / andando.</td></tr></table>\n <div class=\"ojo\"><b>a + el = al</b>: <span class=\"es-t\">Voy al aeropuerto.</span> (but: <span class=\"es-t\">a la estación</span>)</div>", "gehen, fahren": "to go", "die U-Bahn": "the underground / metro", "der Bus": "the bus", "der Zug": "the train", "das Auto": "the car", "das Fahrrad": "the bicycle", "das Flugzeug": "the plane", "zu Fuß": "on foot", "die Linie": "the line", "die Haltestelle": "the stop", "der Bahnhof / die Station": "the station", "umsteigen": "to change (lines)", "aussteigen": "to get off", "nehmen (Verkehrsmittel)": "to take (transport)", "„Ich fahre mit dem Fahrrad.“": "“I go by bike.”", "<table><tr><th>seguir (weitergehen, folgen)</th></tr><tr><td class=\"es-t\">sigo · sigues · sigue · seguimos · seguís · siguen</td></tr></table>\n <div class=\"ojo\">yo <b>sigo</b> – ohne u, damit die Aussprache „g“ bleibt.</div>\n <p><b>tener que + Infinitiv</b> = müssen: <span class=\"es-t\">Tienes que tomar el autobús. Tenéis que bajar en la próxima parada.</span></p>": "<table><tr><th>seguir (to continue, to follow)</th></tr><tr><td class=\"es-t\">sigo · sigues · sigue · seguimos · seguís · siguen</td></tr></table>\n <div class=\"ojo\">yo <b>sigo</b> – without u, so that the “g” sound stays hard.</div>\n <p><b>tener que + infinitive</b> = to have to: <span class=\"es-t\">Tienes que tomar el autobús. Tenéis que bajar en la próxima parada.</span></p>", "Para ir a la feria ___ ___ tomar la línea 1. (du musst)": "Para ir a la feria ___ ___ tomar la línea 1. (you have to)", "Du musst in Plaça Catalunya umsteigen.": "You have to change at Plaça Catalunya.", "Nimm die Metro Linie 3 und steig am Liceu aus.": "Take metro line 3 and get off at Liceu.", "Wissen Sie, wo … ist?": "Do you know where … is?", "Gibt es ein … hier in der Nähe?": "Is there a … near here?", "geradeaus gehen": "to go straight on", "rechts abbiegen": "to turn right", "links abbiegen": "to turn left", "die Straße überqueren": "to cross the street", "bis zum Ende": "to the end", "die erste / zweite Straße": "the first / second street", "in der Nähe (von)": "near (to)", "weit weg (von)": "far (from)", "gegenüber (von)": "opposite", "neben": "next to", "vor / hinter": "in front of / behind", "zwischen … und …": "between … and …", "La farmacia está ___ el banco ___ la panadería. (zwischen … und …)": "La farmacia está ___ el banco ___ la panadería. (between … and …)", "Höflich nach dem Weg fragen:": "Asking for directions politely:", "Wo ist der Bahnhof?": "Where is the station?", "Du suchst den Weg zur Metro. Du sprichst einen Passanten an.": "You're looking for the way to the metro. You speak to a passer-by.", "Sprich den Passanten höflich an.": "Address the passer-by politely.", "Unbestimmt (eine Station) → <b>hay</b>.": "Indefinite (a station) → <b>hay</b>.", "Ja, ganz nah. Geh geradeaus und bieg in die zweite Straße links ab.": "Yes, very close. Go straight on and take the second street on the left.", "Wiederhole zur Sicherheit.": "Repeat it to be sure.", "Er hat <i>izquierda</i> (links) gesagt.": "He said <i>izquierda</i> (left).", "Genau. Die Station ist gegenüber von einer Bank.": "Exactly. The station is opposite a bank.", "<i>De nada</i> sagt man, wenn sich jemand bei <b>dir</b> bedankt.": "You say <i>de nada</i> when someone thanks <b>you</b>.", "Gern geschehen. Alles Gute!": "You're welcome. All the best!", "Bieg rechts ab und geh bis zum Ende der Straße.": "Turn right and go to the end of the street.", "Zuerst geradeaus, dann links abbiegen.": "First straight on, then turn left.", "Das Hotel ist neben dem Museum.": "The hotel is next to the museum.", "Barcelona es una ciudad muy {atractiva|attraktiv} para hacer negocios. Tiene un {puerto|Hafen} muy importante, un aeropuerto internacional y más de 300 {ferias|Messen} y congresos al año, como el Mobile World Congress.\n\nLa ciudad tiene unas 2500 horas de sol al año. Por eso muchas personas {extranjeras|ausländisch} quieren vivir aquí. En el centro hay edificios de todos los estilos: {góticos|gotisch} en el Barri Gòtic y {modernistas|im Jugendstil} en el Eixample, como la Casa Batlló.\n\nMoverse por la ciudad es fácil porque el metro es rápido y barato. Pero en {hora punta|Stoßzeit} hay mucha gente y mucho tráfico. Muchos barceloneses prefieren ir en bici: hay más de 300 kilómetros de {carril bici|Radweg}.": "Barcelona es una ciudad muy {atractiva|attractive} para hacer negocios. Tiene un {puerto|port} muy importante, un aeropuerto internacional y más de 300 {ferias|trade fairs} y congresos al año, como el Mobile World Congress.\n\nLa ciudad tiene unas 2500 horas de sol al año. Por eso muchas personas {extranjeras|foreign} quieren vivir aquí. En el centro hay edificios de todos los estilos: {góticos|Gothic} en el Barri Gòtic y {modernistas|Art Nouveau} en el Eixample, como la Casa Batlló.\n\nMoverse por la ciudad es fácil porque el metro es rápido y barato. Pero en {hora punta|rush hour} hay mucha gente y mucho tráfico. Muchos barceloneses prefieren ir en bici: hay más de 300 kilómetros de {carril bici|cycle lanes}.", "Barcelona ist eine sehr attraktive Stadt, um Geschäfte zu machen. Sie hat einen sehr wichtigen Hafen, einen internationalen Flughafen und mehr als 300 Messen und Kongresse pro Jahr, wie den Mobile World Congress.\n\nDie Stadt hat etwa 2500 Sonnenstunden im Jahr. Deshalb wollen viele Ausländer hier leben. Im Zentrum gibt es Gebäude aller Stilrichtungen: gotische im Barri Gòtic und Jugendstil-Bauten im Eixample, wie die Casa Batlló.\n\nSich in der Stadt fortzubewegen ist einfach, weil die Metro schnell und günstig ist. Aber zur Stoßzeit gibt es viele Leute und viel Verkehr. Viele Barcelonesen fahren lieber Fahrrad: Es gibt mehr als 300 Kilometer Radwege.": "Barcelona is a very attractive city for doing business. It has a very important port, an international airport and more than 300 trade fairs and conferences a year, such as the Mobile World Congress.\n\nThe city has about 2,500 hours of sunshine a year. That's why many foreigners want to live here. In the centre there are buildings of every style: Gothic ones in the Barri Gòtic and Art Nouveau (modernista) ones in the Eixample, like the Casa Batlló.\n\nGetting around the city is easy because the metro is fast and cheap. But at rush hour there are lots of people and lots of traffic. Many people from Barcelona prefer to cycle: there are more than 300 kilometres of cycle lanes.", "<table><tr><td class=\"es-t\">porque</td><td>weil (Grund)</td><td class=\"es-t\">Es fácil llegar porque está cerca del aeropuerto.</td></tr>\n <tr><td class=\"es-t\">por eso</td><td>deshalb (Folge)</td><td class=\"es-t\">Está cerca del aeropuerto, por eso es fácil llegar.</td></tr>\n <tr><td class=\"es-t\">pero</td><td>aber</td><td class=\"es-t\">El metro es rápido, pero hay mucha gente.</td></tr>\n <tr><td class=\"es-t\">y / también</td><td>und / auch</td><td class=\"es-t\">Hay parques y también playas.</td></tr></table>\n <div class=\"ojo\"><b>¿Por qué?</b> (warum?, getrennt + Akzent) – <b>porque</b> (weil, zusammen).</div>": "<table><tr><td class=\"es-t\">porque</td><td>because (reason)</td><td class=\"es-t\">Es fácil llegar porque está cerca del aeropuerto.</td></tr>\n <tr><td class=\"es-t\">por eso</td><td>that's why (consequence)</td><td class=\"es-t\">Está cerca del aeropuerto, por eso es fácil llegar.</td></tr>\n <tr><td class=\"es-t\">pero</td><td>but</td><td class=\"es-t\">El metro es rápido, pero hay mucha gente.</td></tr>\n <tr><td class=\"es-t\">y / también</td><td>and / also</td><td class=\"es-t\">Hay parques y también playas.</td></tr></table>\n <div class=\"ojo\"><b>¿Por qué?</b> (why?, two words + accent) – <b>porque</b> (because, one word).</div>", "Beschreibe deinen Weg zur Uni (oder zu einem Lieblingsort in Barcelona) und dein Viertel in 5–7 Sätzen.": "Describe your way to university (or to a favourite place in Barcelona) and your neighbourhood in 5–7 sentences.", "hay/estar, ir + en/a, tener que, Wegbeschreibung, Konnektoren": "hay/estar, ir + en/a, tener que, giving directions, connectors", "📎 Übungsblatt: Explicar el camino": "📎 Worksheet: Explicar el camino", "Aus deinem Kurs (Semester 5) · hay oder está?": "From a university Spanish course (semester 5) · hay or está?", "<i>un</i> aparcamiento = irgendeiner → <b>hay</b>.": "<i>un</i> aparcamiento = any one → <b>hay</b>.", "Präpositionen: a(l), de(l), en, por": "Prepositions: a(l), de(l), en, por", "<h3>Stadt beschreiben</h3><p class=\"es-t\">Barcelona es una ciudad atractiva. Hay muchos bares y restaurantes. La catedral está en el casco antiguo.</p>\n<h3>hay / estar</h3><table><tr><td><b>hay</b> + unbestimmt (un/una, Zahl, mucho …)</td><td class=\"es-t\">Hay una catedral famosa.</td></tr><tr><td><b>está/n</b> + bestimmt (el/la, Name)</td><td class=\"es-t\">¿Dónde está la Sagrada Família?</td></tr></table>\n<h3>muy / mucho</h3><p class=\"es-t\">mucho tráfico, mucha gente, muchos trenes · Es muy fácil. · Trabajo mucho.</p>\n<h3>ir · seguir</h3><table><tr><td>voy, vas, va, vamos, vais, van</td><td>sigo, sigues, sigue, seguimos, seguís, siguen</td></tr></table>\n<p><b>a</b> + Ziel (a + el = <b>al</b>) · <b>en</b> + Verkehrsmittel · <b>a pie</b> · <b>tener que</b> + Infinitiv</p>\n<h3>Weg beschreiben</h3><p class=\"es-t\">Perdone, ¿sabe dónde está …? · Sigue todo recto. · Gira a la derecha / izquierda. · Cruza la calle. · Primero … después … luego … al final …</p>\n<h3>Ortsangaben</h3><p class=\"es-t\">cerca de / lejos de · delante de / detrás de · a la derecha de / a la izquierda de · al lado de · enfrente de · entre … y …</p>\n<h3>Konnektoren</h3><p class=\"es-t\">porque (weil) · por eso (deshalb) · pero (aber)</p>": "<h3>Describing a city</h3><p class=\"es-t\">Barcelona es una ciudad atractiva. Hay muchos bares y restaurantes. La catedral está en el casco antiguo.</p>\n<h3>hay / estar</h3><table><tr><td><b>hay</b> + indefinite (un/una, number, mucho …)</td><td class=\"es-t\">Hay una catedral famosa.</td></tr><tr><td><b>está/n</b> + definite (el/la, name)</td><td class=\"es-t\">¿Dónde está la Sagrada Família?</td></tr></table>\n<h3>muy / mucho</h3><p class=\"es-t\">mucho tráfico, mucha gente, muchos trenes · Es muy fácil. · Trabajo mucho.</p>\n<h3>ir · seguir</h3><table><tr><td>voy, vas, va, vamos, vais, van</td><td>sigo, sigues, sigue, seguimos, seguís, siguen</td></tr></table>\n<p><b>a</b> + destination (a + el = <b>al</b>) · <b>en</b> + transport · <b>a pie</b> · <b>tener que</b> + infinitive</p>\n<h3>Giving directions</h3><p class=\"es-t\">Perdone, ¿sabe dónde está …? · Sigue todo recto. · Gira a la derecha / izquierda. · Cruza la calle. · Primero … después … luego … al final …</p>\n<h3>Location</h3><p class=\"es-t\">cerca de / lejos de · delante de / detrás de · a la derecha de / a la izquierda de · al lado de · enfrente de · entre … y …</p>\n<h3>Connectors</h3><p class=\"es-t\">porque (because) · por eso (that's why) · pero (but)</p>"};
